/**
 * A world's own picture, taken from inside it by its owner: the current
 * view rendered at a card's shape, without the shell's panels (the engine
 * renders the scene alone into a target of that size), then written where
 * the world's placements description says, with the visitor's pass.
 */
import type { Scene } from '@babylonjs/core/scene';

/** A card's shape: what the directory and a world's page show. */
export const PICTURE_SIZE = { width: 1280, height: 720 };

export type SaveResult = { ok: true } | { ok: false; error: string };

/** The current view as a PNG, or null where there is no camera to take it from. The engine's capture loads only when asked. */
export async function shootView(scene: Scene): Promise<Blob | null> {
  const camera = scene.activeCamera;
  if (!camera) return null;
  const { CreateScreenshotUsingRenderTargetAsync } = await import('@babylonjs/core/Misc/screenshotTools');
  const data = await CreateScreenshotUsingRenderTargetAsync(scene.getEngine(), camera, PICTURE_SIZE, 'image/png');
  return pictureFromDataUrl(data);
}

/** The engine's data URL as a picture, decoded here: a world page's connect-src refuses a fetch of a data: URL. */
export function pictureFromDataUrl(data: string): Blob {
  const comma = data.indexOf(',');
  const type = /^data:([^;,]+)/.exec(data)?.[1] ?? 'image/png';
  const text = atob(data.slice(comma + 1));
  const bytes = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i += 1) bytes[i] = text.charCodeAt(i);
  return new Blob([bytes], { type });
}

/** Writes the picture where the world says; a refusal comes back in plain words. */
export async function savePicture(o: { fetchImpl: typeof fetch; url: string; pass: string | null; picture: Blob }): Promise<SaveResult> {
  if (!o.pass) return { ok: false, error: 'Sign in to set the picture.' };
  let status: number;
  try {
    status = (await o.fetchImpl(o.url, { method: 'PUT', headers: { authorization: `Bearer ${o.pass}`, 'content-type': o.picture.type || 'image/png' }, body: o.picture })).status;
  } catch {
    status = 503;
  }
  if (status >= 200 && status < 300) return { ok: true };
  return {
    ok: false,
    error:
      status === 401
        ? 'Sign in again to set the picture.'
        : status === 403
          ? 'Only the world’s owner sets its picture.'
          : status === 413
            ? 'That picture is too big: up to 2 MB.'
            : status === 415
              ? 'That is not a picture the world takes.'
              : 'The store is not answering; try again in a moment.',
  };
}
