/**
 * Adding a template to a world's palette: a model (glb), a name, an
 * optional picture and optional triggers, written to the store with the
 * visitor's pass. A template is three files beside each other under the
 * store's `assets/`: the picture, the model, and the model's description
 * (`<name>.glb.veml`, its sidecar), a small VEML document carrying the
 * label, the picture's name and the triggers. They are written in that
 * order, so the files the description names exist by the time the store
 * reads it.
 *
 * Only a visitor whose scopes include `palette` is offered this; the store
 * checks again and refuses anyone else.
 */
import type { PrefabBinding } from './placements';

/** A trigger as the Add form writes it. */
export type TemplateBinding = Pick<PrefabBinding, 'on' | 'animate' | 'clip' | 'loop' | 'action'>;

const NAME = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const MODEL_MAX = 25 * 1024 * 1024;
const PICTURE_MAX = 2 * 1024 * 1024;
const SIDECAR_MAX = 64 * 1024;
const PICTURE_TYPES: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };
const HINTS_NS = 'http://www.fivesqd.com/schemas/veml/4.0/profiles/client-hints';

/** A template's name as typed, if it is a safe file name: letters, digits, `-` and `_`, at most 64. */
export function templateName(raw: string): string | null {
  const name = raw.trim();
  return NAME.test(name) ? name : null;
}

const escape = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/**
 * The description for a template: VEML 4.0 declaring the client-hints
 * profile, the picture as its preview, and one `hints:binding` per trigger,
 * directly among the environment's content, where core VEML admits profile
 * vocabulary.
 */
export function sidecarText(name: string, o: { picture?: string; bindings: readonly TemplateBinding[] }): string {
  const binding = (b: TemplateBinding): string => {
    const attrs: [string, string | undefined][] = [
      ['on', b.on],
      ['animate', b.animate],
      ['clip', b.clip],
      ['loop', b.loop === undefined ? undefined : String(b.loop)],
      ['action', b.action],
    ];
    const written = attrs.filter(([, v]) => v !== undefined && v !== '').map(([k, v]) => ` ${k}="${escape(v!)}"`);
    return `<hints:binding${written.join('')}/>`;
  };
  return (
    `<veml xmlns="http://www.fivesqd.com/schemas/veml/4.0" xmlns:hints="${HINTS_NS}" version="4.0">` +
    `<metadata><title>${escape(name)}</title>` +
    (o.picture ? `<preview src="${escape(o.picture)}"/>` : '') +
    '<profile>client-hints</profile></metadata>' +
    `<environment>${o.bindings.map(binding).join('')}</environment>` +
    '</veml>'
  );
}

/**
 * The names of a glb's animations, read from its JSON chunk, so the Add
 * form can offer the model's own clips. Anything that is not a glb has none.
 */
export function glbAnimationNames(bytes: ArrayBuffer): string[] {
  try {
    if (bytes.byteLength < 20) return [];
    const v = new DataView(bytes);
    // "glTF", then the JSON chunk's length and type ("JSON").
    if (v.getUint32(0, true) !== 0x46546c67 || v.getUint32(16, true) !== 0x4e4f534a) return [];
    const length = v.getUint32(12, true);
    if (20 + length > bytes.byteLength) return [];
    const json = JSON.parse(new TextDecoder().decode(new Uint8Array(bytes, 20, length))) as { animations?: unknown };
    if (!Array.isArray(json.animations)) return [];
    return json.animations.map((a) => (a as { name?: unknown })?.name).filter((n): n is string => typeof n === 'string' && n !== '');
  } catch {
    return [];
  }
}

const refusal = (status: number): string =>
  status === 401
    ? 'Sign in again to add templates.'
    : status === 403
      ? 'You don’t have permission to add templates to this world.'
      : status === 413
        ? 'That file is too big for this world.'
        : status === 415
          ? 'The store did not take that kind of file: a model must be a glb, and a picture a PNG, JPEG or WebP.'
          : status === 404
            ? 'That name can’t be used; try letters and numbers.'
            : 'The store is not answering; try again in a moment.';

export type UploadResult = { ok: true; ref: string } | { ok: false; error: string };

/** Writes a template's files to the store: picture, model, sidecar; stops at the first refusal and says why. */
export async function uploadTemplate(o: {
  fetchImpl: typeof fetch;
  /** What palette references resolve against: the palette's own address. */
  base: string;
  pass: string | null;
  name: string;
  model: Blob;
  picture?: Blob;
  bindings: readonly TemplateBinding[];
}): Promise<UploadResult> {
  const name = templateName(o.name);
  if (!o.pass) return { ok: false, error: 'Sign in to add templates.' };
  if (!name) return { ok: false, error: 'A name is letters, numbers, - and _ (up to 64), starting with a letter or number.' };
  if (o.model.size > MODEL_MAX) return { ok: false, error: 'That model is too big: a world takes models of up to 25 MB.' };
  let pictureFile: string | undefined;
  if (o.picture) {
    const ext = PICTURE_TYPES[o.picture.type];
    if (!ext) return { ok: false, error: 'A picture is a PNG, JPEG or WebP.' };
    if (o.picture.size > PICTURE_MAX) return { ok: false, error: 'That picture is too big: up to 2 MB.' };
    pictureFile = `${name}.${ext}`;
  }
  const sidecar = sidecarText(name, { ...(pictureFile ? { picture: pictureFile } : {}), bindings: o.bindings });
  if (new TextEncoder().encode(sidecar).length > SIDECAR_MAX) return { ok: false, error: 'Too many triggers for one template.' };

  const put = async (file: string, body: Blob | string, type: string): Promise<string | null> => {
    try {
      const r = await o.fetchImpl(new URL(`assets/${file}`, o.base).href, {
        method: 'PUT',
        headers: { authorization: `Bearer ${o.pass}`, 'content-type': type },
        body,
      });
      return r.ok ? null : refusal(r.status);
    } catch {
      return refusal(503);
    }
  };
  const steps: [string, Blob | string, string][] = [
    ...(o.picture && pictureFile ? ([[pictureFile, o.picture, o.picture.type]] as [string, Blob, string][]) : []),
    [`${name}.glb`, o.model, 'model/gltf-binary'],
    [`${name}.glb.veml`, sidecar, 'application/xml'],
  ];
  for (const [file, body, type] of steps) {
    const error = await put(file, body, type);
    if (error) return { ok: false, error };
  }
  return { ok: true, ref: `assets/${name}.glb` };
}
