/**
 * Getting a pass for a store that takes writes (client-hints profile,
 * **The placements description** → planet profile, **Signing in to
 * write**): the visitor signs in with the shell's own upstream issuer in a
 * popup, and the shell exchanges that sign-in at a pass issuer it trusts
 * for a pass made for one audience and one write origin. The store never
 * sees the sign-in. The primitives are the planet's (`planet/signIn.ts`);
 * this is the order they run in, for any store, with no element of its own.
 */
import {
  discoverIssuer,
  exchangeForPass,
  finishSignIn,
  loadShellSignIn,
  passIssuerFor,
  passIssuerUsed,
  shellBaseFrom,
  startSignIn,
  upstreamToken,
  usePassIssuer,
  type IssuerEndpoints,
  type KeyStore,
  type ShellSignIn,
  type SignInReturn,
  type TrustedPassIssuer,
} from '../planet/signIn';
import { planetTokenFor } from '../planet/planetEdit';

const RETRY_EXCHANGE_MS = 30_000;

export interface PassFlowOptions {
  /** The pass issuer the store names, the client id the pass is for, and the write origin it is for. */
  passIssuer: string;
  audience: string;
  resource: string;
  fetchImpl: (url: string, init?: RequestInit) => Promise<Response>;
  /** Whether the store vouches for the description (read elsewhere); no pass is sought or sent before it does. */
  vouched: () => boolean;
  say: (text: string) => void;
  keep?: KeyStore;
  pending?: KeyStore;
  shellBase?: string;
  redirectUri?: string;
  shellSignIn?: () => Promise<ShellSignIn | null>;
  openWindow?: (url: string) => Window | null;
  exitPointerLock?: () => void;
  /** Told when a pass arrives, so what waits on one (the edit bar, the sign-in notice) moves on without waiting for input. */
  changed?: () => void;
  /** Takes the whole page to an address, for a sign-in made in place; by default the page's own location. */
  navigate?: (url: string) => void;
}

/** Where a sign-in made in place comes back to, and what came back from it: this tab's session, read by signin-done.js. */
const RETURN_TO = 'webverse:sign-in-return-to';
const RETURNED = 'webverse:sign-in-returned';

export interface PassFlow {
  /** The pass held for this store, or null. */
  token(): string | null;
  /** Whether this shell can sign the visitor in for this store at all (its own configuration names the pass issuer). */
  trusted(): boolean | null;
  /** The visitor's sign-in with this shell's own issuer, held in this tab, or null: what a pass is exchanged from. */
  upstream(): string | null;
  /** What the visitor pressing "sign in" starts: reuse this tab's sign-in, or open the popup. */
  begin(): void;
  /** Signs in from this page itself, with no popup and so no click: to the issuer and back to `here`. */
  beginHere(here: string): void;
  /** Exchanges this tab's sign-in for a pass, now that the store vouches (after a sign-in made in place). */
  resume(): void;
  /** Resolves when nothing is in flight. */
  idle(): Promise<void>;
  dispose(): void;
}

export function createPassFlow(o: PassFlowOptions): PassFlow {
  const pending = new Set<Promise<unknown>>();
  const track = <T>(p: Promise<T>): Promise<T> => {
    pending.add(p);
    void p.finally(() => pending.delete(p));
    return p;
  };
  let disposed = false;
  const keep = (): KeyStore | undefined => o.keep ?? globalThis.localStorage;
  const pendingStore = (): KeyStore | undefined => o.pending ?? globalThis.sessionStorage;
  const shellBase = o.shellBase ?? shellBaseFrom(import.meta.url, import.meta.env.DEV);
  const returnPage = o.redirectUri ?? new URL('signin-done.html', shellBase).href;

  let found: { config: ShellSignIn; passIssuer: TrustedPassIssuer; upstream: IssuerEndpoints | null } | null = null;
  let trusted: boolean | null = null;
  const finding = track(
    (async () => {
      const config = await (o.shellSignIn ?? (() => loadShellSignIn(shellBase, (u) => globalThis.fetch(u))))();
      const passIssuer = config ? passIssuerFor(config, o.passIssuer) : null;
      if (!config || !passIssuer) {
        trusted = false;
        return null;
      }
      trusted = true;
      found = { config, passIssuer, upstream: await discoverIssuer(config.issuer, o.fetchImpl) };
      return found;
    })(),
  );

  const upstream = (): string | null => {
    const held = pendingStore();
    return found && held ? upstreamToken(held, found.config.issuer, found.config.clientId) : null;
  };
  const used = (): boolean => {
    const held = pendingStore();
    return !!found && !!held && passIssuerUsed(held, found.passIssuer.issuer);
  };
  let exchanging = false;
  let refusedAt = -Infinity;
  const exchange = (): void => {
    const kept = keep();
    const subject = upstream();
    if (!found || !kept || !subject || !o.vouched() || !used() || exchanging || Date.now() - refusedAt < RETRY_EXCHANGE_MS) return;
    exchanging = true;
    void track(
      exchangeForPass({ passIssuer: found.passIssuer.issuer, exchange: found.passIssuer.tokenEndpoint, subjectToken: subject, audience: o.audience, resource: o.resource, keep: kept, fetchImpl: o.fetchImpl }).then((out) => {
        exchanging = false;
        if (disposed) return;
        if (out.ok) return o.changed?.();
        refusedAt = Date.now();
        o.say(out.reason === 'invalid_target' ? 'This world is not one your sign-in can edit.' : 'The pass could not be had; try again later.');
      }),
    );
  };

  const onMessage = (e: MessageEvent): void => {
    const d = e.data as Partial<SignInReturn> & { type?: unknown };
    if (disposed || !o.vouched() || e.origin !== new URL(returnPage).origin || !d || d.type !== 'sign-in:return') return;
    const held = pendingStore();
    if (!held) return;
    const message: SignInReturn = { code: typeof d.code === 'string' ? d.code : null, state: typeof d.state === 'string' ? d.state : null, error: typeof d.error === 'string' ? d.error : null };
    void track(
      (async () => {
        const out = await finishSignIn({ origin: e.origin, message, pending: held, fetchImpl: o.fetchImpl });
        if (disposed) return;
        o.say(out.ok ? 'Signed in: you can edit this world.' : out.reason === 'access_denied' ? 'Sign-in cancelled.' : 'Sign-in did not finish; try again.');
        if (out.ok) exchange();
      })(),
    );
  };
  globalThis.addEventListener?.('message', onMessage);

  // Back from a sign-in made in place: the return page kept what came back
  // for this tab. Finished once, here; the pass waits for the store to vouch.
  {
    const held = pendingStore();
    const raw = held?.getItem(RETURNED) ?? null;
    if (held && raw) {
      held.removeItem(RETURNED);
      let d: Partial<SignInReturn> = {};
      try {
        d = JSON.parse(raw) as Partial<SignInReturn>;
      } catch {
        d = {};
      }
      const message: SignInReturn = { code: typeof d.code === 'string' ? d.code : null, state: typeof d.state === 'string' ? d.state : null, error: typeof d.error === 'string' ? d.error : null };
      void track(
        (async () => {
          await finding;
          const out = await finishSignIn({ origin: new URL(returnPage).origin, message, pending: held, fetchImpl: o.fetchImpl });
          if (disposed) return;
          if (!out.ok) return o.say(out.reason === 'access_denied' ? 'Sign-in cancelled.' : 'Sign-in did not finish; try again.');
          exchange();
        })(),
      );
    }
  }

  return {
    token: () => {
      const kept = keep();
      return kept ? planetTokenFor({ issuer: o.passIssuer, signIn: { clientId: o.audience }, writeOrigin: o.resource }, (k) => kept.getItem(k)) : null;
    },
    trusted: () => trusted,
    upstream,
    begin() {
      const held = pendingStore();
      if (!held || !o.vouched()) return;
      void track(
        (async () => {
          const where = await finding;
          if (!where) return o.say('This WebVerse can’t sign you in to edit this world.');
          usePassIssuer(held, where.passIssuer.issuer);
          if (upstream()) return exchange();
          if (!where.upstream) return o.say('The sign-in could not be reached; try again later.');
          const url = await startSignIn({ issuer: where.config.issuer, clientId: where.config.clientId, redirectUri: returnPage, endpoints: where.upstream, pending: held });
          o.exitPointerLock?.();
          const opened = o.openWindow ? o.openWindow(url) : globalThis.open?.(url, 'webverse-sign-in', 'popup,width=480,height=640');
          if (!opened) o.say('The browser blocked the sign-in window: allow pop-ups for this page and try again.');
        })(),
      );
    },
    beginHere(here) {
      const held = pendingStore();
      if (!held || !o.vouched()) return;
      void track(
        (async () => {
          const where = await finding;
          if (!where) return o.say('This WebVerse can’t sign you in to edit this world.');
          usePassIssuer(held, where.passIssuer.issuer);
          if (upstream()) return exchange();
          if (!where.upstream) return o.say('The sign-in could not be reached; try again later.');
          const url = await startSignIn({ issuer: where.config.issuer, clientId: where.config.clientId, redirectUri: returnPage, endpoints: where.upstream, pending: held });
          if (disposed) return;
          held.setItem(RETURN_TO, here);
          (o.navigate ?? ((u: string) => globalThis.location?.assign(u)))(url);
        })(),
      );
    },
    resume() {
      void track(finding.then(() => exchange()));
    },
    async idle() {
      while (pending.size > 0) await Promise.all([...pending]);
    },
    dispose() {
      disposed = true;
      globalThis.removeEventListener?.('message', onMessage);
    },
  };
}
