/**
 * Placements: the things people put into a world after it was published,
 * kept in a store the document points at (client-hints profile,
 * `hints:placements`). This module reads the description a document names,
 * loads the store's snapshot and palette, and turns each placement into a
 * mesh entity the session draws beside the document's own. Reading is
 * sessionless and needs no sign-in; writing is placementEditor.ts.
 *
 * The rules a description is held to are the profile's: one known format;
 * the store and the palette on one https origin (loopback excepted), which
 * is also the write origin; an `edit` is usable only with a policy and an
 * issuer; relative addresses resolve against the description's own.
 */
import type { VemlMeshEntity, VemlPrimitiveEntity, VemlPrimitiveType, VemlQuaternion, VemlVec3 } from '../../veml/documentModel';

/**
 * The language's own shapes as items (VEML core §4.5): a reference
 * `primitive:<shape>` names a primitive, is never looked up in the palette,
 * and is drawn in the colour its placement's overrides carry.
 */
const SHAPES: ReadonlyArray<[shape: string, type: VemlPrimitiveType, label: string]> = [
  ['cube', 'cubemesh', 'Cube'],
  ['sphere', 'spheremesh', 'Sphere'],
  ['capsule', 'capsulemesh', 'Capsule'],
  ['cylinder', 'cylindermesh', 'Cylinder'],
  ['plane', 'planemesh', 'Plane'],
  ['torus', 'torusmesh', 'Torus'],
  ['cone', 'conemesh', 'Cone'],
  ['rectangular-pyramid', 'rectangularpyramidmesh', 'Pyramid'],
  ['tetrahedron', 'tetrahedronmesh', 'Tetrahedron'],
  ['prism', 'prismmesh', 'Prism'],
  ['arch', 'archmesh', 'Arch'],
];
const SHAPE_PREFIX = 'primitive:';
/** A shape with no colour of its own is this grey. */
export const SHAPE_DEFAULT_COLOR = '#9a9a9a';
export const isShapeRef = (ref: string): boolean => ref.startsWith(SHAPE_PREFIX);
/** The shape a reference names, or undefined for a reference to a model or a shape the language lacks. */
export const shapeOf = (ref: string): { shape: string; type: VemlPrimitiveType; label: string } | undefined => {
  if (!isShapeRef(ref)) return undefined;
  const found = SHAPES.find(([shape]) => shape === ref.slice(SHAPE_PREFIX.length));
  return found ? { shape: found[0], type: found[1], label: found[2] } : undefined;
};
/** The shapes as palette items, in the language's order. */
export const SHAPE_PREFABS: readonly Prefab[] = SHAPES.map(([shape, , label]) => ({ ref: `${SHAPE_PREFIX}${shape}`, label, shape }));

export interface PlacementTransform {
  position: VemlVec3;
  rotation: VemlQuaternion;
  scale: VemlVec3;
}

/** A placement as the store serves it (the profile's snapshot wire form). */
export interface Placement {
  id: string;
  prefab_ref: string;
  transform: PlacementTransform;
  overrides: Record<string, unknown>;
  seq: number;
  wid?: string;
}

export interface PlacementsSnapshot {
  world_seq: number;
  placements: Placement[];
  tombstones: { id: string; wid?: string; seq: number }[];
  tombstone_floor: number | 'none';
  /** What a place quotes in ?if_absent: the store's own floor as of this snapshot, which it may move with every write. */
  retention_floor: number | 'none';
}

/**
 * A trigger on a palette item, as its sidecar declares it: when (`on`:
 * click, touch, place), what to do with one of the placed copy's own clips
 * (`animate`: play, stop, toggle; `clip`, `loop`), and a named world action
 * to fire. Data only; fields the shell does not know are kept and unused.
 */
export interface PrefabBinding {
  on: string;
  animate?: string;
  clip?: string;
  loop?: boolean;
  action?: string;
  node?: string;
  [field: string]: unknown;
}

export interface Prefab {
  ref: string;
  label?: string;
  thumbnail?: string;
  bindings?: PrefabBinding[];
  /** Set on the language's shapes (SHAPE_PREFABS): the shape's name, as `primitive`'s `shape` says it. */
  shape?: string;
  /**
   * The same item in several looks: a style's name to its model, each a
   * reference resolved as `ref` is (client-hints profile, **Styles**). The
   * names are the palette's own, not a fixed list, and are not ranked.
   */
  styles?: Record<string, string>;
}

/** A style's name: lower-case letters, digits and `-`, 1 to 32 characters. */
export const isStyleName = (v: unknown): v is string => typeof v === 'string' && /^[a-z0-9-]{1,32}$/.test(v);

/**
 * The model to draw an item in `style`: that style's model where the item
 * has it, else the item's own `ref`. A placement still names `ref`.
 */
export function modelOf(prefab: Pick<Prefab, 'ref' | 'styles'>, style: string | undefined): string {
  // Only the item's own styles: never a property every object inherits, such as `constructor`.
  const own = style !== undefined && prefab.styles && Object.prototype.hasOwnProperty.call(prefab.styles, style) ? prefab.styles[style] : undefined;
  return typeof own === 'string' && own !== '' ? own : prefab.ref;
}

/**
 * The style in force: the visitor's own choice; else the world's
 * `placements.style`; else none, and every item draws its own `ref`.
 * `auto`, and anything that is not a style name, chooses nothing.
 */
export function styleOf(choice: string | undefined, worldHint: string | null | undefined): string | undefined {
  if (choice !== 'auto' && isStyleName(choice)) return choice;
  if (worldHint !== 'auto' && isStyleName(worldHint)) return worldHint;
  return undefined;
}

/** A binding as served, with each known field kept only when it has its type. */
const readBinding = (raw: unknown): PrefabBinding | null => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const b = { ...(raw as Record<string, unknown>) };
  if (typeof b.on !== 'string' || b.on === '') return null;
  for (const k of ['animate', 'clip', 'action', 'node']) if (k in b && typeof b[k] !== 'string') delete b[k];
  if ('loop' in b && typeof b.loop !== 'boolean') delete b.loop;
  return b as PrefabBinding;
};

export interface PlacementsEdit {
  policy: 'owner' | 'signed-in' | 'grants';
  issuer: string;
  clientId?: string;
  /** Under `grants`: where a visitor's pass asks what they may do, on the write origin. */
  grants?: string;
}

export interface PlacementsDescription {
  entities: string;
  palette?: string;
  /** The store's origin: the pass goes there and nowhere else. */
  writeOrigin: string;
  edit?: PlacementsEdit;
  /** The room writes are told in; with `topic`, notices name the topic and not the description (The change notice). */
  changes?: { address: string; session: string; topic?: string };
  /** Where the world's own picture is written by its owner, on the store's origin. */
  picture?: string;
}

export interface PlacementsWarning {
  kind: 'diagnostic';
  name: string;
  path: string;
}

const FORMAT = 'placements/1';
const LOOPBACK = new Set(['localhost', '127.0.0.1', '[::1]']);

const warn = (name: string, path: string): PlacementsWarning => ({ kind: 'diagnostic', name: `veml:placements:${name}`, path });

const resolveAgainst = (raw: unknown, base: string): string | null => {
  if (typeof raw !== 'string' || raw === '') return null;
  try {
    return new URL(raw, base).toString();
  } catch {
    return null;
  }
};

/** The origin a store address may have: https, or plain http on loopback. */
const storeOrigin = (url: string): string | null => {
  try {
    const u = new URL(url);
    if (u.protocol === 'https:') return u.origin;
    if (u.protocol === 'http:' && LOOPBACK.has(u.hostname)) return u.origin;
    return null;
  } catch {
    return null;
  }
};

/** Reads a placements description as fetched, held to the profile's rules. `null` with a warning where nothing is drawn. */
export function readPlacementsDescription(json: unknown, descriptionUrl: string): { description: PlacementsDescription | null; warnings: PlacementsWarning[] } {
  const warnings: PlacementsWarning[] = [];
  const d = (json ?? {}) as Record<string, unknown>;
  if (d.format !== FORMAT) {
    warnings.push(warn('unknown-format', `${descriptionUrl}: format ${JSON.stringify(d.format)}`));
    return { description: null, warnings };
  }
  const entities = resolveAgainst(d.entities, descriptionUrl);
  if (!entities) {
    warnings.push(warn('invalid', `${descriptionUrl}: no entities address`));
    return { description: null, warnings };
  }
  const writeOrigin = storeOrigin(entities);
  if (!writeOrigin) {
    warnings.push(warn('other-origin', `${descriptionUrl}: the store must be https (${entities})`));
    return { description: null, warnings };
  }
  const palette = resolveAgainst(d.palette, descriptionUrl) ?? undefined;
  if (palette !== undefined && storeOrigin(palette) !== writeOrigin) {
    warnings.push(warn('other-origin', `${descriptionUrl}: the palette must be on the store's origin (${palette})`));
    return { description: null, warnings };
  }

  let edit: PlacementsEdit | undefined;
  const e = d.edit as Record<string, unknown> | undefined;
  if (e && typeof e === 'object' && (e.policy === 'owner' || e.policy === 'signed-in' || e.policy === 'grants') && typeof e.issuer === 'string' && e.issuer !== '') {
    const signIn = e.signIn as Record<string, unknown> | undefined;
    const clientId = signIn && typeof signIn.clientId === 'string' && signIn.clientId !== '' ? signIn.clientId : undefined;
    // Under `grants`, the address to ask is required, and on the store's one origin.
    const grants = e.policy === 'grants' ? resolveAgainst(e.grants, descriptionUrl) : null;
    if (grants !== null && storeOrigin(grants) !== writeOrigin) {
      warnings.push(warn('other-origin', `${descriptionUrl}: edit.grants must be on the store's origin (${grants})`));
      return { description: null, warnings };
    }
    if (e.policy !== 'grants' || grants !== null) {
      edit = { policy: e.policy, issuer: e.issuer, ...(clientId !== undefined ? { clientId } : {}), ...(grants !== null ? { grants } : {}) };
    }
  }

  let changes: PlacementsDescription['changes'];
  const c = d.changes as Record<string, unknown> | undefined;
  if (c && typeof c === 'object' && c.type === 'worldsync' && typeof c.address === 'string' && typeof c.session === 'string') {
    changes = { address: c.address, session: c.session, ...(typeof c.topic === 'string' && c.topic ? { topic: c.topic } : {}) };
  }

  // The world's picture is written with the pass, so only on the store's own origin; elsewhere it names nothing.
  let picture = resolveAgainst(d.picture, descriptionUrl) ?? undefined;
  if (picture !== undefined && storeOrigin(picture) !== writeOrigin) {
    warnings.push(warn('other-origin', `${descriptionUrl}: the picture must be on the store's origin (${picture})`));
    picture = undefined;
  }

  return {
    description: { entities, ...(palette !== undefined ? { palette } : {}), writeOrigin, ...(edit ? { edit } : {}), ...(changes ? { changes } : {}), ...(picture !== undefined ? { picture } : {}) },
    warnings,
  };
}

const isVec3 = (v: unknown): v is VemlVec3 => !!v && typeof v === 'object' && ['x', 'y', 'z'].every((k) => typeof (v as Record<string, unknown>)[k] === 'number');
const isQuat = (v: unknown): v is VemlQuaternion => isVec3(v) && typeof (v as unknown as Record<string, unknown>).w === 'number';

/** The snapshot as fetched, with anything that is not a placement left out. */
export function readSnapshot(json: unknown): PlacementsSnapshot {
  const s = (json ?? {}) as Record<string, unknown>;
  const placements: Placement[] = [];
  for (const raw of Array.isArray(s.placements) ? s.placements : []) {
    const p = raw as Record<string, unknown>;
    const t = p.transform as Record<string, unknown> | undefined;
    if (typeof p.id !== 'string' || typeof p.prefab_ref !== 'string' || !t || !isVec3(t.position) || !isQuat(t.rotation) || !isVec3(t.scale)) continue;
    placements.push({
      id: p.id,
      prefab_ref: p.prefab_ref,
      transform: { position: t.position, rotation: t.rotation, scale: t.scale },
      overrides: p.overrides && typeof p.overrides === 'object' ? (p.overrides as Record<string, unknown>) : {},
      seq: typeof p.seq === 'number' ? p.seq : 0,
      ...(typeof p.wid === 'string' ? { wid: p.wid } : {}),
    });
  }
  const tombstones = (Array.isArray(s.tombstones) ? s.tombstones : [])
    .map((x) => x as Record<string, unknown>)
    .filter((x) => typeof x.id === 'string' && typeof x.seq === 'number')
    .map((x) => ({ id: x.id as string, seq: x.seq as number, ...(typeof x.wid === 'string' ? { wid: x.wid } : {}) }));
  return {
    world_seq: typeof s.world_seq === 'number' ? s.world_seq : 0,
    placements,
    tombstones,
    tombstone_floor: typeof s.tombstone_floor === 'number' ? s.tombstone_floor : 'none',
    retention_floor: typeof s.retention_floor === 'number' ? s.retention_floor : 'none',
  };
}

/** The palette as fetched; without one, the snapshot's own references, unlabelled. */
export function readPalette(json: unknown, snapshot: PlacementsSnapshot): Prefab[] {
  const p = (json ?? {}) as Record<string, unknown>;
  const prefabs = (Array.isArray(p.prefabs) ? p.prefabs : [])
    .map((x) => x as Record<string, unknown>)
    .filter((x) => typeof x.ref === 'string' && x.ref !== '')
    .map((x) => {
      const bindings = (Array.isArray(x.bindings) ? x.bindings : []).map(readBinding).filter((b): b is PrefabBinding => b !== null);
      // Style names only, each with a non-empty string; anything else is ignored.
      const raw = x.styles && typeof x.styles === 'object' && !Array.isArray(x.styles) ? (x.styles as Record<string, unknown>) : {};
      const styles = Object.fromEntries(Object.entries(raw).filter(([k, v]) => isStyleName(k) && typeof v === 'string' && v !== '')) as Record<string, string>;
      return {
        ref: x.ref as string,
        ...(typeof x.label === 'string' ? { label: x.label } : {}),
        ...(typeof x.thumbnail === 'string' ? { thumbnail: x.thumbnail } : {}),
        ...(bindings.length > 0 ? { bindings } : {}),
        ...(Object.keys(styles).length > 0 ? { styles } : {}),
      };
    });
  if (json !== undefined) return prefabs;
  return [...new Set(snapshot.placements.map((x) => x.prefab_ref))].map((ref) => ({ ref }));
}

export interface LoadedPlacements {
  snapshot: PlacementsSnapshot;
  palette: Prefab[];
  /** What prefab references resolve against: the palette's address, else the snapshot's. */
  paletteBase: string;
}

/** Fetches the store's snapshot and, where there is one, its palette. */
export async function loadPlacements(o: { description: PlacementsDescription; fetchImpl: typeof fetch }): Promise<LoadedPlacements> {
  const { description, fetchImpl } = o;
  const snapshotRes = await fetchImpl(description.entities, { headers: { accept: 'application/json' } });
  if (!snapshotRes.ok) throw new Error(`the placements store answered ${snapshotRes.status} for ${description.entities}`);
  const snapshot = readSnapshot(await snapshotRes.json());
  let paletteJson: unknown;
  if (description.palette) {
    const r = await fetchImpl(description.palette, { headers: { accept: 'application/json' } });
    if (r.ok) paletteJson = await r.json();
  }
  return { snapshot, palette: readPalette(paletteJson, snapshot), paletteBase: description.palette ?? description.entities };
}

export interface PlacementsForWorld extends LoadedPlacements {
  description: PlacementsDescription;
  descriptionUrl: string;
  warnings: PlacementsWarning[];
}

/**
 * Everything a world's placements need, from its hints: null, and nothing
 * fetched, for a document that names no description; null with warnings
 * for one the shell cannot use.
 */
export async function placementsFor(o: {
  hint: (name: string) => string;
  documentUrl: string;
  fetchImpl: typeof fetch;
}): Promise<PlacementsForWorld | null> {
  const src = o.hint('placements.src');
  if (!src) return null;
  const descriptionUrl = resolveAgainst(src, o.documentUrl);
  if (!descriptionUrl) return null;
  const res = await o.fetchImpl(descriptionUrl, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`the placements description answered ${res.status} (${descriptionUrl})`);
  const read = readPlacementsDescription(await res.json(), descriptionUrl);
  if (!read.description) return { description: { entities: '', writeOrigin: '' }, descriptionUrl, snapshot: readSnapshot({}), palette: [], paletteBase: '', warnings: read.warnings };
  const loaded = await loadPlacements({ description: read.description, fetchImpl: o.fetchImpl });
  return { description: read.description, descriptionUrl, ...loaded, warnings: read.warnings };
}

/** The entity id a placement is drawn under. */
export const placementEntityId = (id: string): string => `placement:${id}`;

/** What a placement is drawn as: a model from the palette, or one of the language's shapes. */
export type PlacementEntity = VemlMeshEntity | VemlPrimitiveEntity;

/**
 * One entity per placement: a mesh resolved against the palette's address, or a primitive for a
 * `primitive:<shape>` reference. A model the palette does not list, or a shape the language does
 * not have, is skipped with a warning.
 */
export function placementEntities(snapshot: PlacementsSnapshot, palette: readonly Prefab[], paletteBase: string, style?: string): { entities: PlacementEntity[]; warnings: PlacementsWarning[] } {
  const entities: PlacementEntity[] = [];
  const warnings: PlacementsWarning[] = [];
  const known = new Map(palette.map((p) => [p.ref, p]));
  for (const p of snapshot.placements) {
    if (isShapeRef(p.prefab_ref)) {
      const shape = shapeOf(p.prefab_ref);
      if (!shape) {
        warnings.push(warn('unknown-prefab', `${p.id}: ${p.prefab_ref} is not a shape the language has; skipped`));
        continue;
      }
      entities.push(shapeEntity(p, shape.type));
      continue;
    }
    const prefab = known.get(p.prefab_ref);
    if (!prefab) {
      warnings.push(warn('unknown-prefab', `${p.id}: ${p.prefab_ref} is not in the palette; skipped`));
      continue;
    }
    entities.push(placementEntity(p, prefab, paletteBase, style));
  }
  return { entities, warnings };
}

const transformOf = (p: Placement) => ({ kind: 'scaletransform' as const, position: p.transform.position, rotation: p.transform.rotation, scale: p.transform.scale });

/** The mesh entity for one placement of a model, drawn in `style` where the item has it. */
export function placementEntity(p: Placement, prefab: Prefab, paletteBase: string, style?: string): VemlMeshEntity {
  const model = prefab.ref === p.prefab_ref ? modelOf(prefab, style) : p.prefab_ref;
  const resolved = resolveAgainst(model, paletteBase) ?? model;
  return {
    type: 'mesh',
    id: placementEntityId(p.id),
    tag: p.id,
    ...(prefab.label !== undefined ? { meshName: prefab.label } : {}),
    // `raw` stays the placement's own reference; only what loads follows the style.
    meshResources: [{ raw: p.prefab_ref, resolved }],
    transform: transformOf(p),
    children: [],
    placementSockets: [],
  };
}

/** The primitive entity for one placement of a shape, in its overrides' colour or the shell's grey. */
export function shapeEntity(p: Placement, type: VemlPrimitiveType): VemlPrimitiveEntity {
  const color = typeof p.overrides.color === 'string' && p.overrides.color !== '' ? p.overrides.color : SHAPE_DEFAULT_COLOR;
  return { type, id: placementEntityId(p.id), tag: p.id, color, transform: transformOf(p), children: [], placementSockets: [] };
}
