/**
 * The placement editor: what a visitor who may write does to a world's
 * placements (client-hints profile, `hints:placements`, **Writing a
 * placement**). Each change is predicted at once through the draw
 * callbacks and sent to the store with the visitor's pass; a refusal puts
 * the prediction back and says why; every outcome reaches the world's
 * script as the `placements.edit` action. A change notice from the room
 * reads the snapshot again, once per newer sequence.
 *
 * This module holds no scene and no DOM: the session gives it the draw
 * callbacks, the pass and the hints, and tests give it fakes.
 */
import type { Placement, PlacementTransform, PlacementsDescription, PlacementsSnapshot } from './placements';
import { readSnapshot } from './placements';

export type EditOp = 'place' | 'move' | 'delete';
export type EditReason = 'sign-in' | 'not-allowed' | 'not-found' | 'changed' | 'invalid' | 'unavailable';

export interface PlacementEditorOptions {
  description: PlacementsDescription;
  /** The description's own address, which the store's vouching file must list. */
  descriptionUrl: string;
  snapshot: PlacementsSnapshot;
  /** The world's hint in force, by name (`placements.edit`, …). */
  hint: (name: string) => string;
  /** The visitor's pass for this store, or null when they are not signed in. */
  pass: () => string | null;
  fetchImpl: typeof fetch;
  /** Draw a placement that was not drawn; redraw one at a new transform; take one away. */
  draw: (p: Placement) => void;
  redraw: (p: Placement) => void;
  undraw: (id: string) => void;
  /** A line for the visitor. */
  notify: (message: string) => void;
  /** Fire an action on the world's bus. */
  act: (name: string, data: unknown) => void;
  /** Told when what is offered may have changed without a call from the view (a grants answer arrived). */
  changed?: () => void;
  /** Mints a placement id. Default: a short random one. */
  newId?: () => string;
}

export interface PlacementEditor {
  /** Resolves once the store's vouching file has been read. */
  ready(): Promise<void>;
  /** Whether editing is offered right now. */
  offered(): boolean;
  /** Why it is not, when it is not. */
  reason(): 'hint-off' | 'no-edit' | 'sign-in' | 'not-vouched' | 'checking' | 'not-granted' | null;
  /** What the store's grants gave the visitor's current pass (`placement`, `palette`, …); none before an answer, or without grants. */
  scopes(): readonly string[];
  current(): PlacementsSnapshot;
  /** Places an item, with what its copy carries beyond its transform (a shape's `color`); `{}` for a model. */
  place(prefabRef: string, transform: PlacementTransform, overrides?: Record<string, unknown>): Promise<string>;
  move(id: string, transform: PlacementTransform): Promise<void>;
  remove(id: string): Promise<void>;
  /** A change notice from the room: the store's world_seq after a write. */
  onNotice(worldSeq: number): void;
  /** Reads the snapshot again now; resolves with it. */
  refresh(): Promise<PlacementsSnapshot>;
  /** Draws every placement in the current snapshot that is not drawn, and takes away those that are gone. */
  dispose(): void;
}

export interface EditKeys {
  place: string;
  grab: string;
  delete: string;
}

const DEFAULT_KEYS: EditKeys = { place: 'mouse-left', grab: 'mouse-right', delete: 'delete' };
const MOUSE = new Set(['mouse-left', 'mouse-middle', 'mouse-right']);
/** A key as `KeyboardEvent.key` gives it in lower case, or one of the three mouse buttons. */
const isInput = (p: string): boolean => (p.startsWith('mouse-') ? MOUSE.has(p) : /^([a-z0-9]|[a-z][a-z0-9-]{1,30})$/.test(p));

/** Three inputs from the hint (place, grab, delete), `auto` otherwise; the visitor's own setting, in the same form, wins. */
export function editKeys(hint: string, visitor?: string): EditKeys {
  const parse = (v: string | undefined): EditKeys | null => {
    if (!v || v === 'auto') return null;
    const parts = v.trim().toLowerCase().split(/\s+/);
    if (parts.length !== 3 || !parts.every(isInput)) return null;
    return { place: parts[0]!, grab: parts[1]!, delete: parts[2]! };
  };
  return parse(visitor) ?? parse(hint) ?? DEFAULT_KEYS;
}

const reasonOf = (status: number): EditReason =>
  status === 401 ? 'sign-in' : status === 403 ? 'not-allowed' : status === 404 ? 'not-found' : status === 412 ? 'changed' : status === 400 || status === 413 ? 'invalid' : 'unavailable';

const said: Record<EditReason, string> = {
  'sign-in': 'Sign in to edit this world.',
  'not-allowed': 'This world is edited by its owner.',
  'not-found': 'That is no longer there.',
  changed: 'That changed under you; the world was read again.',
  invalid: 'The store refused that change.',
  unavailable: 'The store is not answering; try again in a moment.',
};

/**
 * What the visitor is told. A full world and too many writes are both
 * `unavailable` to a script (the profile's reason for a 5xx or no answer),
 * but trying again does not help a full world, so the visitor hears which.
 */
const noticeFor = (status: number, r: EditReason): string =>
  status === 507 ? 'This world is full; delete something to make room.' : status === 429 ? 'Too many changes at once; wait a moment and try again.' : said[r];
/** What a visitor is told when the store's grants give them no editing. */
const NOT_GRANTED = 'The owner of this world hasn’t given you editing.';

export function createPlacementEditor(o: PlacementEditorOptions): PlacementEditor {
  let snapshot = o.snapshot;
  let vouched: boolean | null = null;

  // Under `grants`, what this visitor may do, asked of the store once per
  // pass (client-hints profile, Who may write). A 401 is a sign-in again;
  // any other failure offers nothing until the pass changes.
  const grantsUrl = o.description.edit?.policy === 'grants' ? o.description.edit.grants : undefined;
  let granted: { pass: string; answer: 'placement' | 'none' | 'sign-in'; scopes: string[] } | null = null;
  let asking: string | null = null;
  const ask = async (pass: string): Promise<void> => {
    if (!grantsUrl || asking === pass) return;
    asking = pass;
    let answer: 'placement' | 'none' | 'sign-in' = 'none';
    let scopes: string[] = [];
    try {
      const r = await o.fetchImpl(grantsUrl, { headers: { accept: 'application/json', authorization: `Bearer ${pass}` } });
      if (r.status === 401) answer = 'sign-in';
      else if (r.ok) {
        const j = (await r.json()) as { scopes?: unknown };
        scopes = Array.isArray(j.scopes) ? j.scopes.filter((s): s is string => typeof s === 'string') : [];
        answer = scopes.includes('placement') ? 'placement' : 'none';
      }
    } catch {
      // Unanswered: nothing is offered, and the next pass asks again.
    }
    if (asking !== pass) return;
    asking = null;
    granted = { pass, answer, scopes };
    if (answer === 'none') o.notify(NOT_GRANTED);
    o.changed?.();
  };
  const newId = o.newId ?? (() => `p_${Math.random().toString(36).slice(2, 10)}`);

  const ready = (async () => {
    if (!o.description.edit) {
      vouched = false;
      return;
    }
    try {
      const r = await o.fetchImpl(`${o.description.writeOrigin}/.well-known/placement-writes.json`, { headers: { accept: 'application/json' } });
      const j = r.ok ? ((await r.json()) as { descriptions?: unknown }) : {};
      vouched = Array.isArray(j.descriptions) && j.descriptions.includes(o.descriptionUrl);
    } catch {
      vouched = false;
    }
    const pass = o.pass();
    if (vouched && pass) await ask(pass);
  })();

  const reason = (): ReturnType<PlacementEditor['reason']> => {
    if (o.hint('placements.edit') === 'none') return 'hint-off';
    if (!o.description.edit) return 'no-edit';
    if (vouched === false) return 'not-vouched';
    const pass = o.pass();
    if (!pass) return 'sign-in';
    if (grantsUrl) {
      if (granted?.pass !== pass) {
        if (vouched) void ask(pass);
        return 'checking';
      }
      if (granted.answer === 'sign-in') return 'sign-in';
      if (granted.answer === 'none') return 'not-granted';
    }
    return null;
  };
  const offered = (): boolean => reason() === null && vouched === true;

  const writeUrl = (id: string): string => `${o.description.entities}/${encodeURIComponent(id)}`;
  // After our own write the store's sequence is the ack's, and a store that
  // moves its floor with every write (the Floor does) has moved it there too;
  // a floor that did not move is corrected by the next snapshot, and a stale
  // quote is a 412 that reads it again.
  const afterWrite = (seq: number | undefined): Partial<Pick<PlacementsSnapshot, 'world_seq' | 'retention_floor'>> =>
    seq === undefined ? {} : { world_seq: seq, retention_floor: snapshot.retention_floor === 'none' ? 'none' : seq };

  // One refetch at a time; a notice that arrives while one is under way is
  // acted on once more after it, however many arrived, never once per notice.
  let fetching: Promise<PlacementsSnapshot> | null = null;
  let again = false;
  const refresh = (): Promise<PlacementsSnapshot> => {
    if (fetching) {
      again = true;
      return fetching;
    }
    fetching = (async () => {
      try {
        const r = await o.fetchImpl(o.description.entities, { headers: { accept: 'application/json' } });
        if (r.ok) apply(readSnapshot(await r.json()));
      } catch {
        // The world keeps what it has; the next notice or write reads again.
      } finally {
        fetching = null;
      }
      if (again) {
        again = false;
        void refresh();
      }
      return snapshot;
    })();
    return fetching;
  };
  const apply = (next: PlacementsSnapshot): void => {
    const before = new Map(snapshot.placements.map((p) => [p.id, p]));
    for (const p of next.placements) {
      const was = before.get(p.id);
      if (!was) o.draw(p);
      else if (JSON.stringify(was.transform) !== JSON.stringify(p.transform) || was.prefab_ref !== p.prefab_ref) o.redraw(p);
      before.delete(p.id);
    }
    for (const id of before.keys()) o.undraw(id);
    snapshot = next;
  };

  const refused = (op: EditOp, p: { id: string; prefab_ref: string }, status: number): void => {
    const r = reasonOf(status);
    o.notify(r === 'not-allowed' && grantsUrl ? NOT_GRANTED : noticeFor(status, r));
    o.act('placements.edit', { op, id: p.id, prefab_ref: p.prefab_ref, result: 'refused', reason: r });
    if (r === 'changed') void refresh();
  };
  const applied = (op: EditOp, p: { id: string; prefab_ref: string }): void => {
    o.act('placements.edit', { op, id: p.id, prefab_ref: p.prefab_ref, result: 'applied' });
  };

  const send = async (method: 'PUT' | 'DELETE', url: string, precondition: Record<string, string>, body?: unknown): Promise<{ status: number; seq?: number }> => {
    const pass = o.pass();
    if (!pass) return { status: 401 };
    try {
      const r = await o.fetchImpl(url, {
        method,
        headers: { authorization: `Bearer ${pass}`, ...precondition, ...(body !== undefined ? { 'content-type': 'application/json' } : {}) },
        ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
      });
      let seq: number | undefined;
      try {
        const j = (await r.json()) as { seq?: unknown };
        if (typeof j.seq === 'number') seq = j.seq;
      } catch {
        // No body, or not JSON: the status says enough.
      }
      return { status: r.status, ...(seq !== undefined ? { seq } : {}) };
    } catch {
      return { status: 503 };
    }
  };

  return {
    ready: () => ready,
    offered,
    scopes: () => (granted && granted.pass === o.pass() ? granted.scopes : []),
    reason,
    current: () => snapshot,
    refresh,
    onNotice(worldSeq) {
      if (worldSeq <= snapshot.world_seq) return;
      void refresh();
    },
    async place(prefabRef, transform, overrides = {}) {
      const id = newId();
      if (!offered()) return id;
      const p: Placement = { id, prefab_ref: prefabRef, transform, overrides, seq: 0 };
      snapshot = { ...snapshot, placements: [...snapshot.placements, p] };
      o.draw(p);
      // Always a conditional write: a bare PUT would overwrite a live placement at this id.
      const url = `${writeUrl(id)}?if_absent=${snapshot.retention_floor}`;
      const r = await send('PUT', url, {}, { prefab_ref: prefabRef, transform, overrides });
      if (r.status === 200) {
        snapshot = { ...snapshot, ...afterWrite(r.seq), placements: snapshot.placements.map((x) => (x.id === id ? { ...x, seq: r.seq ?? x.seq } : x)) };
        applied('place', p);
      } else {
        snapshot = { ...snapshot, placements: snapshot.placements.filter((x) => x.id !== id) };
        o.undraw(id);
        refused('place', p, r.status);
      }
      return id;
    },
    async move(id, transform) {
      if (!offered()) return;
      const was = snapshot.placements.find((p) => p.id === id);
      if (!was) return;
      const moved: Placement = { ...was, transform };
      snapshot = { ...snapshot, placements: snapshot.placements.map((p) => (p.id === id ? moved : p)) };
      o.redraw(moved);
      const r = await send('PUT', writeUrl(id), { 'if-match': `"${was.seq}"` }, { prefab_ref: was.prefab_ref, transform, overrides: was.overrides });
      if (r.status === 200) {
        snapshot = { ...snapshot, ...afterWrite(r.seq), placements: snapshot.placements.map((p) => (p.id === id ? { ...p, seq: r.seq ?? p.seq } : p)) };
        applied('move', was);
      } else {
        snapshot = { ...snapshot, placements: snapshot.placements.map((p) => (p.id === id ? was : p)) };
        o.redraw(was);
        refused('move', was, r.status);
      }
    },
    async remove(id) {
      if (!offered()) return;
      const was = snapshot.placements.find((p) => p.id === id);
      if (!was) return;
      snapshot = { ...snapshot, placements: snapshot.placements.filter((p) => p.id !== id) };
      o.undraw(id);
      const r = await send('DELETE', writeUrl(id), { 'if-match': `"${was.seq}"` });
      if (r.status === 200) {
        snapshot = { ...snapshot, ...afterWrite(r.seq) };
        applied('delete', was);
      } else {
        snapshot = { ...snapshot, placements: [...snapshot.placements, was] };
        o.draw(was);
        refused('delete', was, r.status);
      }
    },
    dispose() {
      again = false;
    },
  };
}
