/** How long a chosen item's name stays above the dock, on a screen without a pointer to hover with. */
const NAME_SHOWN_MS = 1500;
const NO_BUILDING: BuildingTools = { snap: false, grid: 1, rotateStep: 15 };

/** A model loaded for the placing copy: outside the world's entities, so nothing walks on it or picks it. */
export interface PreviewModel {
  root: TransformNode;
  meshes: readonly AbstractMesh[];
  dispose(): void;
}
const BUTTONS: Record<number, string> = { 0: 'mouse-left', 1: 'mouse-middle', 2: 'mouse-right' };
const KEYS_SETTING = 'webverse:placements-edit-keys';
const BUILDING_SETTING = 'webverse:placements-building';

/** A socket as the shell opens one; narrow so a test can hand in its own. */
export interface ChangesSocket {
  send(data: string): void;
  close(): void;
  addEventListener(type: 'open' | 'message' | 'close', fn: (e: { data?: unknown }) => void): void;
}

/**
 * The styles a world's items name, and the visitor's choice among them. The
 * choice lasts while the visitor is in that world and is never saved.
 */
export interface StyleOffer {
  /** The style names, sorted and each once; empty when the world names none. */
  readonly names: readonly string[];
  /** The visitor's choice, or undefined for the world's own. */
  current(): string | undefined;
  /** Draws what is placed, and the copy in hand, in `name`; `auto` or undefined returns to the world's choice. A name not in `names` is ignored. */
  choose(name: string | undefined): void;
}

/** The page's own address without `sign-in=now`, when it asks to sign in on arrival; otherwise null. */
const signInRequested = (): string | null => {
  const here = globalThis.location?.href;
  if (!here) return null;
  const url = new URL(here);
  if (url.searchParams.get('sign-in') !== 'now') return null;
  url.searchParams.delete('sign-in');
  return url.href;
};

export interface PlacementsViewOptions {
  scene: Scene;
  camera: { globalPosition: Vector3; getDirection(axis: Vector3): Vector3 };
  /**
   * The nearest mesh the ray from `origin` along `dir` meets within `reach`, among those `pick` admits.
   * The session casts it: the view imports no engine module of its own, so its chunk shares nothing
   * new with the first paint (see tests/unit/placementsFirstPaint.test.ts).
   */
  cast: (origin: Vector3, dir: Vector3, reach: number, pick: (mesh: AbstractMesh) => boolean) => PickingInfo | null;
  canvas: HTMLElement | null;
  documentUrl: string;
  hint: (name: string) => string | null;
  fetchImpl: typeof fetch;
  /** Builds entities into the world (the session's own composer), and finds what it built. */
  build: (entities: PlacementEntity[]) => Promise<void>;
  entity: (entityId: string) => { rootNode?: TransformNode; ownedMeshes(): readonly AbstractMesh[]; dispose(): void } | undefined;
  act: (name: string, data: unknown) => void;
  /** A line for the visitor. Default: a toast at the top of the page. */
  say?: (text: string) => void;
  warn: (name: string, path: string) => void;
  /** Test seams: a pass flow of the test's own, a socket of its own, storage of its own. */
  passFlow?: (o: { passIssuer: string; audience: string; resource: string; vouched: () => boolean; changed?: () => void }) => PassFlow;
  openSocket?: (url: string) => ChangesSocket;
  keep?: KeyStore;
  pending?: KeyStore;
  shellSignIn?: () => Promise<ShellSignIn | null>;
  shellBase?: string;
  redirectUri?: string;
  openWindow?: (url: string) => Window | null;
  /**
   * Where to come back to after signing in on arrival, or null. A link that
   * opens the world asks for it with `?sign-in=now` on the page's address
   * (a directory's own Open button, for someone who came to build); the
   * visitor is then signed in in place, with no click, and returns to the
   * page without the request. Default: read from the page's address.
   */
  signInOnArrival?: () => string | null;
  /**
   * Told of the visitor's sign-in with this shell's own issuer, once for each one this tab holds: when it is made in
   * the world, or held already as the world loads. Who signs in to edit is who the visitor is, and the shell may name
   * them by it.
   */
  onSignedIn?: (upstream: string) => void;
  /** Whether the touch sticks and their buttons are on screen, which the dock keeps clear of. Default: a touch-first device. */
  touchControls?: boolean;
  /**
   * Told the styles the palette's items name (client-hints **Styles**) each
   * time the palette is read, with a way to choose one, so the visitor can be
   * offered them; told an empty offer when the world is left.
   */
  offerStyles?: (offer: StyleOffer) => void;
  /** The visitor's own edit keys, where they set some. Default: localStorage. */
  visitorKeys?: () => string | undefined;
  /** Loads a model for the placing copy. Default: the session's glTF chunk, loaded when someone first places. */
  preview?: (url: string) => Promise<PreviewModel>;
  /** The visitor's building tools, read each frame, and where a change to them is kept. Default: localStorage, like the edit keys. */
  building?: () => Partial<BuildingTools>;
  saveBuilding?: (tools: BuildingTools) => void;
}

/** A button a world's script put in the bar: its name, its picture, and what a press does. */
export interface DockTool {
  id: string;
  name: string;
  picture: string | null;
  press: () => void;
}

/**
 * The default copy loader: the item's model through the glTF chunk every
 * world with a glb already loads, outside the entity registry so nothing
 * walks on it, collides with it or picks it, its clips still, under a root
 * of its own so the glTF root keeps its handedness flip.
 */
const loadPreview = async (url: string, scene: Scene, fetchImpl: typeof fetch): Promise<PreviewModel> => {
  const res = await fetchImpl(url);
  if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
  const bytes = await res.arrayBuffer();
  const { loadGlbContainer } = await import('../../engine/gltfChunk');
  const container = await loadGlbContainer(bytes, scene, 'placement-preview.glb', scene.getEngine().isWebGPU ? 'webgpu' : undefined);
  container.addAllToScene();
  for (const g of container.animationGroups) g.stop();
  const root = container.createRootMesh();
  return { root, meshes: container.meshes.filter((m) => m !== root), dispose: () => container.dispose() };
};

export interface PlacementsView {
  /** Resolves once the store was read and the placements drawn. */
  ready(): Promise<void>;
  state(): {
    drawn: number;
    worldSeq: number;
    offered: boolean;
    reason: string | null;
    holding: string | null;
    chosen: string | null;
    /** The item being placed, while its copy follows the pointer. */
    placing: string | null;
    keys: EditKeys;
  };
  /** Resolves when nothing is in flight. */
  idle(): Promise<void>;
  /**
   * A world's script's tool in the bar and the Build menu (the profile's `Dock`): its id, or null
   * where the world offers no editing bar or the bar's nine slots hold nothing but tools.
   */
  addTool(name: string, picture: string | null, press: () => void): string | null;
  removeTool(id: string): boolean;
  clearTools(): void;
  dispose(): void;
}

export function createPlacementsView(o: PlacementsViewOptions): PlacementsView {
  const pending = new Set<Promise<unknown>>();
  const track = <T>(p: Promise<T>): Promise<T> => {
    pending.add(p);
    void p.finally(() => pending.delete(p));
    return p;
  };
  let disposed = false;
  const doc = typeof document === 'undefined' ? undefined : document;
  const hint = (name: string): string => o.hint(name) ?? '';
  let toast: HTMLElement | undefined;
  let toastTimer: ReturnType<typeof setTimeout> | undefined;
  const say = (text: string): void => {
    if (o.say) return o.say(text);
    if (!doc) return;
    if (!toast) {
      toast = doc.createElement('div');
      toast.dataset.placementsToast = '';
      toast.style.cssText = 'position:fixed;left:50%;top:16px;transform:translateX(-50%);display:none;padding:10px 16px;border-radius:6px;background:rgba(0,0,0,.7);color:#fff;font:14px system-ui,sans-serif;z-index:22';
      doc.body.appendChild(toast);
    }
    toast.textContent = text;
    toast.style.display = 'block';
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(() => void (toast && (toast.style.display = 'none')), 4000);
  };

  let loaded: PlacementsForWorld | null = null;
  let editor: PlacementEditor | undefined;
  let flow: PassFlow | undefined;
  /** The sign-in last told to the shell (`onSignedIn`), so each one is told once. */
  let toldSignIn: string | null = null;
  const tellSignIn = (): void => {
    const up = flow?.upstream() ?? null;
    if (!up || up === toldSignIn || disposed) return;
    toldSignIn = up;
    o.onSignedIn?.(up);
  };
  let socket: ChangesSocket | undefined;
  let closedRoom = false;
  let holding: string | null = null;
  /** How far the held placement's origin sits above its lowest point, measured as it is taken hold of. */
  let heldLift = 0;
  let chosen: string | null = null;
  let barEl: HTMLElement | undefined;
  let noticeEl: HTMLButtonElement | undefined;
  let section: BuildSection | undefined;
  /** The bar and its Build button, side by side at the foot of the screen. */
  let dockEl: HTMLElement | undefined;
  let openBuildEl: HTMLButtonElement | undefined;
  /** The dock's stylesheet, and the name shown above it. */
  let dockStyleEl: HTMLStyleElement | undefined;
  let nameEl: HTMLElement | undefined;
  let nameTimer: ReturnType<typeof setTimeout> | undefined;
  /** The Build menu: a panel of its own, apart from WebVerse's menu, as the old MyWorlds had it. */
  let panelEl: HTMLElement | undefined;
  const panelOpen = (): boolean => !!panelEl && !panelEl.hidden;
  const closePanel = (): void => {
    if (panelEl) panelEl.hidden = true;
  };
  const openPanel = (): void => {
    if (!panelEl || !offered()) return;
    section?.refresh();
    panelEl.hidden = false;
    // The visitor needs the pointer to choose.
    doc?.exitPointerLock?.();
  };
  let prefabs: Prefab[] = [];
  /** The language's shapes, offered unless the world says `placements.shapes="none"`. */
  const shapes = (): readonly Prefab[] => (hint('placements.shapes') === 'none' ? [] : SHAPE_PREFABS);
  /** Everything the bar and the catalog can hold: the palette, then the shapes. */
  const items = (): Prefab[] => [...prefabs, ...shapes()];
  /** The colour the next shape is placed in; the Build menu's colour row sets it. */
  let shapeColor = SHAPE_DEFAULT_COLOR;
  /** A script's tools, by id, in the order they were added. */
  const dockTools = new Map<string, DockTool>();
  let toolCount = 0;
  const isTool = (ref: string): boolean => ref.startsWith('tool:');
  /** The bar's nine slots, by prefab reference or tool id, and the one the visitor last chose. */
  let slots: string[] = [];
  let slot = 0;
  /** The item being placed: where its copy stands (last frame's point), and the copy once it has loaded. */
  /** The item being placed: its copy once loaded, and the least corner of its bounds from its origin, measured unturned. */
  let placing: { ref: string; at: Vector3 | null; model?: PreviewModel; corner?: { x: number; y: number; z: number } } | null = null;
  /** The placing copy's turn, in degrees; kept from one item to the next, as builders place rows. */
  let yaw = 0;
  /** The placement the pointer is on, for touch triggers. */
  let touched: string | null = null;
  /** Each drawn placement's build, so a trigger can wait for its clips. */
  const builds = new Map<string, Promise<void>>();
  const keys = (): EditKeys => editKeys(hint('placements.edit-keys'), (o.visitorKeys ?? (() => globalThis.localStorage?.getItem(KEYS_SETTING) ?? undefined))());
  // The visitor's building tools: theirs, kept in this browser beside their edit keys; read once, then kept here.
  let keptTools: Partial<BuildingTools> | undefined;
  const storedTools = (): Partial<BuildingTools> => {
    try {
      const raw = globalThis.localStorage?.getItem(BUILDING_SETTING);
      const t = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
      return {
        ...(typeof t.snap === 'boolean' ? { snap: t.snap } : {}),
        ...(typeof t.grid === 'number' && t.grid > 0 ? { grid: t.grid } : {}),
        ...(typeof t.rotateStep === 'number' && t.rotateStep > 0 ? { rotateStep: t.rotateStep } : {}),
      };
    } catch {
      return {};
    }
  };
  const tools = (): BuildingTools => ({ ...NO_BUILDING, ...(o.building ? o.building() : (keptTools ??= storedTools())) });
  const saveTools = (t: BuildingTools): void => {
    keptTools = t;
    if (o.saveBuilding) return o.saveBuilding(t);
    try {
      globalThis.localStorage?.setItem(BUILDING_SETTING, JSON.stringify(t));
    } catch {
      // Storage refused (private mode, quota): the tools hold for this visit.
    }
  };

  const prefabOf = (ref: string): Prefab | undefined => items().find((p) => p.ref === ref);
  /** The visitor's choice of style in this world: never saved, gone when the world is left. */
  let chosenStyle: string | undefined;
  /** The style in force: the visitor's choice, else the world's `placements.style`, else none. */
  const style = (): string | undefined => styleOf(chosenStyle, hint('placements.style'));
  /** Tells the shell the styles the palette's items name, and how to choose one. */
  const offerStyles = (): void => {
    const names = [...new Set(prefabs.flatMap((p) => Object.keys(p.styles ?? {})))].sort();
    if (chosenStyle !== undefined && !names.includes(chosenStyle)) chosenStyle = undefined;
    o.offerStyles?.({ names, current: () => chosenStyle, choose: (name) => chooseStyle(names, name) });
  };
  const chooseStyle = (names: readonly string[], asked: string | undefined): void => {
    const name = asked === 'auto' ? undefined : asked;
    if (disposed || (name !== undefined && !names.includes(name)) || name === chosenStyle) return;
    chosenStyle = name;
    // What is placed is drawn again in the new style; an item with no styles looks the same in every one.
    for (const p of editor?.current().placements ?? loaded?.snapshot.placements ?? []) {
      if (!prefabOf(p.prefab_ref)?.styles) continue;
      undraw(p.id);
      draw(p);
    }
    if (placing && !isShapeRef(placing.ref)) beginPlacing(placing.ref);
  };
  const clipsOf = (id: string) => clipsUnder(o.scene.animationGroups, o.entity(placementEntityId(id))?.rootNode);
  /** A copy whose item has animation triggers starts still: its triggers, not the model's first clip, decide what plays. */
  const settle = (id: string, prefab: Prefab): void => {
    if (hasAnimate(prefab.bindings)) for (const c of clipsOf(id)) c.stop();
  };
  const draw = (p: Placement): void => {
    if (!loaded) return;
    if (isShapeRef(p.prefab_ref)) {
      // One of the language's shapes, whatever the world says about offering them: a placement already made is drawn.
      const shape = shapeOf(p.prefab_ref);
      if (shape) builds.set(p.id, track(o.build([shapeEntity(p, shape.type)])));
      return;
    }
    const prefab = prefabOf(p.prefab_ref);
    if (!prefab) return;
    builds.set(p.id, track(o.build([placementEntity(p, prefab, loaded.paletteBase, style())]).then(() => settle(p.id, prefab))));
  };
  const redraw = (p: Placement): void => {
    const node = o.entity(placementEntityId(p.id))?.rootNode;
    if (!node) return draw(p);
    const t = p.transform;
    node.position.set(t.position.x, t.position.y, t.position.z);
    node.rotationQuaternion = new Quaternion(t.rotation.x, t.rotation.y, t.rotation.z, t.rotation.w);
    node.scaling.set(t.scale.x, t.scale.y, t.scale.z);
  };
  const undraw = (id: string): void => {
    builds.delete(id);
    o.entity(placementEntityId(id))?.dispose();
  };

  /** Runs a placement's triggers for `on`, on that copy's own clips. */
  const trigger = (on: 'click' | 'touch' | 'place', id: string): void => {
    const p = editor?.current().placements.find((x) => x.id === id);
    const bindings = p ? prefabOf(p.prefab_ref)?.bindings : undefined;
    if (!p || !bindings) return;
    fireTrigger({ on, bindings, clips: clipsOf(id), placement: id, prefab_ref: p.prefab_ref, act: o.act });
  };
  const wantsTouch = (): boolean => prefabs.some((p) => p.bindings?.some((b) => b.on === 'touch'));

  /** The placement whose mesh this is, climbing to the entity's root. */
  const placementAt = (mesh: AbstractMesh | null | undefined): string | null => {
    if (!mesh || !editor) return null;
    for (const p of editor.current().placements) {
      const owned = o.entity(placementEntityId(p.id))?.ownedMeshes() ?? [];
      if (owned.includes(mesh)) return p.id;
    }
    return null;
  };
  /** Where the visitor points: the first thing hit within reach that is not what they hold. */
  const pointed = (): { point: Vector3; placement: string | null } | null => {
    const dir = o.camera.getDirection(Vector3.Forward()).normalize();
    const origin = o.camera.globalPosition.clone();
    const heldMeshes = holding ? (o.entity(placementEntityId(holding))?.ownedMeshes() ?? []) : [];
    const hit = o.cast(origin, dir, REACH_M, (m) => m.isPickable && m.isEnabled() && !heldMeshes.includes(m));
    if (!hit?.hit) return null;
    // A pick carries its distance always, its point not always (a scene with no engine behind it): the point is on the ray either way.
    const point = hit.pickedPoint ?? origin.add(dir.scale(hit.distance));
    return { point, placement: placementAt(hit.pickedMesh) };
  };
  const transformAt = (point: Vector3, like?: PlacementTransform): PlacementTransform => ({
    position: { x: point.x, y: point.y, z: point.z },
    rotation: like?.rotation ?? { x: 0, y: 0, z: 0, w: 1 },
    scale: like?.scale ?? { x: 1, y: 1, z: 1 },
  });

  const offered = (): boolean => !!editor?.offered();
  const showNotice = (): void => {
    if (!noticeEl || !editor) return;
    const r = editor.reason();
    const trusted = flow?.trusted();
    noticeEl.style.display = r === 'sign-in' && hint('placements.edit') !== 'none' ? 'block' : 'none';
    noticeEl.textContent = trusted === false ? 'This WebVerse can’t sign you in to edit this world' : 'Sign in to edit this world';
    const bar = offered() && hint('placements.edit-bar') !== 'none';
    if (dockEl) dockEl.style.display = bar ? 'flex' : 'none';
    if (barEl) barEl.style.display = bar ? 'flex' : 'none';
    if (openBuildEl) openBuildEl.style.display = bar ? 'block' : 'none';
    if (!offered()) {
      cancelPlacing();
      closePanel();
    }
  };

  /**
   * The bar keeps the items the visitor put in it while they are in the palette, and a script's
   * tools while they stand, and fills the rest in palette order, the shapes after the models.
   */
  const fillSlots = (): void => {
    const kept = slots.filter((ref) => (isTool(ref) ? dockTools.has(ref) : prefabOf(ref)));
    for (const t of dockTools.keys()) {
      if (kept.length >= BAR_SLOTS) break;
      if (!kept.includes(t)) kept.push(t);
    }
    // The palette fills the bar; a shape comes into it only when chosen from the catalog.
    for (const p of prefabs) {
      if (kept.length >= BAR_SLOTS) break;
      if (!kept.includes(p.ref)) kept.push(p.ref);
    }
    slots = kept;
    slot = Math.min(slot, Math.max(0, slots.length - 1));
  };
  /** An image element is asked for with its site's cookies: never this page's own site for a world from another. */
  const mayShow = (src: string): boolean => !worldAccessOf(o.scene).refuses(src);
  const pictureIn = (cell: HTMLElement, src: string, alt: string): void => {
    if (!mayShow(src)) return;
    const img = doc!.createElement('img');
    img.src = src;
    img.alt = alt;
    cell.appendChild(img);
  };
  /** Names an item above the dock: while the pointer is on it, or for a moment once it is chosen. */
  const showName = (name: string | null, forMs?: number): void => {
    if (!nameEl) return;
    clearTimeout(nameTimer);
    nameEl.textContent = name ?? '';
    nameEl.hidden = !name;
    if (name && forMs) nameTimer = setTimeout(() => showName(null), forMs);
  };
  const nameOf = (ref: string): string => dockTools.get(ref)?.name ?? prefabOf(ref)?.label ?? ref.split('/').pop() ?? ref;
  const touchControls = o.touchControls ?? (globalThis.window ? detectTouchPrimary(globalThis.window) : false);
  /**
   * Where the dock sits and how many of the bar's slots it shows: all nine where they fit, else only those that fit
   * beside the Build button, which keeps the rest in its catalog. 56 px buttons, 8 px apart, in a panel padded 10 px.
   * At the bottom, 16 px clear of each edge; with the touch sticks showing, between them, 12 px clear of each; and where
   * fewer than three slots fit there (a phone held upright), above the buttons stacked over the sticks, across the
   * whole width.
   */
  const dockLayout = (): { slots: number; bottom: number } => {
    const width = doc?.defaultView?.innerWidth ?? Infinity;
    const fit = (room: number): number => Math.min(BAR_SLOTS, Math.floor((room - 20 + 8) / 64) - 1);
    if (touchControls) {
      const between = fit(width - 2 * (STICK_INSET_PX + STICK_BASE_PX + 12));
      if (between >= 3) return { slots: between, bottom: 16 };
      return { slots: Math.max(1, fit(width - 32)), bottom: TOUCH_BUTTON_BOTTOM_PX + 2 * TOUCH_BUTTON_PX + 24 };
    }
    return { slots: Math.max(1, fit(width - 32)), bottom: 16 };
  };
  const drawBar = (): void => {
    if (!doc || !barEl) return;
    const layout = dockLayout();
    if (dockEl) dockEl.style.bottom = `${layout.bottom}px`;
    if (noticeEl) noticeEl.style.bottom = `${layout.bottom}px`;
    barEl.replaceChildren(
      ...slots.slice(0, layout.slots).flatMap((ref, i) => {
        const cell = doc.createElement('button');
        cell.type = 'button';
        cell.dataset.prefab = ref;
        if (ref === chosen) cell.dataset.chosen = '';
        cell.addEventListener('click', () => chooseSlot(i));
        cell.addEventListener('pointerenter', () => showName(nameOf(ref)));
        cell.addEventListener('pointerleave', () => showName(null));
        const tool = dockTools.get(ref);
        if (tool) {
          cell.title = tool.name;
          if (tool.picture) pictureIn(cell, tool.picture, tool.name);
          else cell.textContent = `${i + 1} ${tool.name}`;
          return [cell];
        }
        const p = prefabOf(ref);
        if (!p) return [];
        cell.title = p.label ?? p.ref;
        if (p.shape) {
          // A shape shows as itself: its name over a swatch of the colour the next one is placed in.
          cell.style.background = `linear-gradient(rgba(0,0,0,.35),rgba(0,0,0,.35)),${shapeColor}`;
          cell.textContent = `${i + 1} ${p.label ?? p.shape}`;
        } else if (p.thumbnail && loaded) pictureIn(cell, new URL(p.thumbnail, loaded.paletteBase).href, p.label ?? p.ref);
        else cell.textContent = `${i + 1} ${p.label ?? p.ref.split('/').pop() ?? p.ref}`;
        return [cell];
      }),
    );
  };

  const yawQuaternion = (): Quaternion => Quaternion.RotationAxis(Vector3.Up(), (yaw * Math.PI) / 180);
  /**
   * Where the copy stands for a point: its lowest point on the surface hit, so a model built about its centre (the
   * language's shapes) stands on the floor rather than half in it; and when the visitor snaps, the corner of its
   * footprint, turned as the copy is, on their grid in x and z, so a piece fills the grid's squares whether its model is
   * built about its centre or from a corner.
   */
  const snapped = (point: Vector3): Vector3 => {
    const t = tools();
    const y = point.y - (placing?.corner?.y ?? 0);
    if (!t.snap || !(t.grid > 0)) return new Vector3(point.x, y, point.z);
    const c = new Vector3(placing?.corner?.x ?? 0, 0, placing?.corner?.z ?? 0).applyRotationQuaternion(yawQuaternion());
    const on = (v: number, d: number): number => Math.round((v + d) / t.grid) * t.grid - d;
    return new Vector3(on(point.x, c.x), y, on(point.z, c.z));
  };
  /** The least corner of a copy's bounds (x, y and z) from its origin, measured before it is moved or turned. */
  const cornerOf = (model: PreviewModel): { x: number; y: number; z: number } => {
    model.root.computeWorldMatrix(true);
    let x = Infinity;
    let y = Infinity;
    let z = Infinity;
    for (const m of model.meshes) {
      if (!m.getTotalVertices()) continue;
      m.computeWorldMatrix(true);
      const b = m.getBoundingInfo().boundingBox;
      x = Math.min(x, b.minimumWorld.x);
      y = Math.min(y, b.minimumWorld.y);
      z = Math.min(z, b.minimumWorld.z);
    }
    const o = model.root.position;
    return Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z) ? { x: x - o.x, y: y - o.y, z: z - o.z } : { x: 0, y: 0, z: 0 };
  };
  const showGhost = (): void => {
    const root = placing?.model?.root;
    if (!root || !placing?.at) return;
    root.position.copyFrom(placing.at);
    root.rotationQuaternion = yawQuaternion();
  };
  const cancelPlacing = (): void => {
    placing?.model?.dispose();
    placing = null;
  };
  const beginPlacing = (ref: string | null): void => {
    if (!ref || !offered() || !loaded || isTool(ref)) return;
    cancelPlacing();
    const p: NonNullable<typeof placing> = { ref, at: null };
    placing = p;
    const shape = shapeOf(ref);
    if (shape) {
      // The shape itself, in the chosen colour, built as the world would build it, under an entity of its
      // own that nothing else names; no model to fetch, and no engine code of the view's own.
      const id = `placement-preview:${shape.shape}`;
      const ghost: Placement = { id: shape.shape, prefab_ref: ref, transform: { position: { x: 0, y: 0, z: 0 }, rotation: { x: 0, y: 0, z: 0, w: 1 }, scale: { x: 1, y: 1, z: 1 } }, overrides: { color: shapeColor }, seq: 0 };
      void track(
        o.build([{ ...shapeEntity(ghost, shape.type), id, tag: id }]).then(
          () => {
            const built = o.entity(id);
            const root = built?.rootNode;
            if (!built || !root) return;
            const model: PreviewModel = { root, meshes: built.ownedMeshes(), dispose: () => built.dispose() };
            if (placing !== p || disposed) return model.dispose();
            for (const m of model.meshes) {
              m.isPickable = false;
              m.checkCollisions = false;
              m.visibility = GHOST_VISIBILITY;
            }
            p.model = model;
            p.corner = cornerOf(model);
            showGhost();
          },
          (err) => o.warn('veml:placements:preview', `${ref}: ${String(err)}`),
        ),
      );
      return;
    }
    // The copy is drawn in the visitor's style, as the placement will be.
    const item = prefabOf(ref);
    const url = new URL(item ? modelOf(item, style()) : ref, loaded.paletteBase).href;
    void track(
      (o.preview ?? ((u: string) => loadPreview(u, o.scene, o.fetchImpl)))(url).then(
        (model) => {
          // Cancelled, or another item chosen, while it loaded: nobody's copy.
          if (placing !== p || disposed) return model.dispose();
          for (const m of model.meshes) {
            m.isPickable = false;
            m.checkCollisions = false;
            m.visibility = GHOST_VISIBILITY;
          }
          p.model = model;
          p.corner = cornerOf(model);
          showGhost();
        },
        (err) => o.warn('veml:placements:preview', `${url}: ${String(err)}`),
      ),
    );
  };
  /** Places the item where its copy stands, as the visitor saw it, and runs its place triggers once on the new copy. */
  const placeAtGhost = (): void => {
    const p = placing;
    if (!p?.at || !editor) return;
    const transform: PlacementTransform = {
      position: { x: p.at.x, y: p.at.y, z: p.at.z },
      rotation: (({ x, y, z, w }) => ({ x, y, z, w }))(yawQuaternion()),
      scale: { x: 1, y: 1, z: 1 },
    };
    const ed = editor;
    // A shape carries its colour with it; a model carries nothing beyond its transform.
    const overrides = isShapeRef(p.ref) ? { color: shapeColor } : {};
    void track(
      (async () => {
        const id = await ed.place(p.ref, transform, overrides);
        await builds.get(id);
        if (ed.current().placements.some((x) => x.id === id)) trigger('place', id);
      })(),
    );
  };

  const chooseSlot = (i: number): void => {
    const ref = slots[i];
    if (!ref) return;
    // A script's tool: a press, and nothing to place.
    const tool = dockTools.get(ref);
    if (tool) return tool.press();
    slot = i;
    chosen = ref;
    drawBar();
    showName(nameOf(ref), NAME_SHOWN_MS);
    beginPlacing(ref);
  };
  /** An item chosen from the catalog goes into the bar's current slot (swapping with its own slot if it has one) and is placed. */
  const chooseFromCatalog = (ref: string): void => {
    const at = slots.indexOf(ref);
    if (at >= 0) slots[at] = slots[slot] ?? ref;
    if (slot < slots.length) slots[slot] = ref;
    else slots.push(ref), (slot = slots.length - 1);
    chosen = ref;
    drawBar();
    beginPlacing(ref);
    // Straight to placing: the menu gets out of the way.
    closePanel();
  };

  // One palette read at a time; notices that arrive during one (the store
  // sends one per file it takes) are read once more after it, together.
  let reading: Promise<void> | null = null;
  let readAgain = false;
  const rereadPalette = (): Promise<void> => {
    if (reading) {
      readAgain = true;
      return reading;
    }
    reading = (async () => {
      do {
        readAgain = false;
        await readPaletteNow();
      } while (readAgain && !disposed);
      reading = null;
    })();
    return reading;
  };
  /** Reads the palette again (after a change notice, or the visitor's own upload) and redraws what it names. */
  const readPaletteNow = async (): Promise<void> => {
    const url = loaded?.description.palette;
    if (!url || !editor) return;
    try {
      const r = await o.fetchImpl(url, { headers: { accept: 'application/json' } });
      if (!r.ok || disposed) return;
      prefabs = readPalette(await r.json(), editor.current());
    } catch {
      // The palette stays as it was; the next notice reads it again.
      return;
    }
    offerStyles();
    fillSlots();
    if (chosen && !prefabOf(chosen)) chosen = slots[0] ?? null;
    if (placing && !prefabOf(placing.ref)) cancelPlacing();
    drawBar();
    section?.refresh();
    // A placement skipped for naming an item the palette lacked is drawn once the palette has it.
    for (const p of editor.current().placements) if (!builds.has(p.id)) draw(p);
  };

  const addTemplate = async (draft: TemplateDraft): Promise<string | null> => {
    if (!loaded) return 'This world has no palette to add to.';
    const r = await uploadTemplate({ fetchImpl: o.fetchImpl, base: loaded.paletteBase, pass: flow?.token() ?? null, ...draft });
    if (!r.ok) return r.error;
    await rereadPalette();
    return null;
  };

  /** How far a placement's origin is above its lowest point, so it stands on what it is moved to. */
  const liftOf = (id: string): number => {
    const built = o.entity(placementEntityId(id));
    const root = built?.rootNode;
    if (!built || !root) return 0;
    root.computeWorldMatrix(true);
    let low = Infinity;
    for (const m of built.ownedMeshes()) {
      if (!m.getTotalVertices()) continue;
      m.computeWorldMatrix(true);
      low = Math.min(low, m.getBoundingInfo().boundingBox.minimumWorld.y);
    }
    return Number.isFinite(low) ? root.getAbsolutePosition().y - low : 0;
  };
  const edit = (what: 'grab' | 'delete'): void => {
    if (!editor || !offered() || !loaded) return;
    if (what === 'grab' && holding) {
      const id = holding;
      holding = null;
      const node = o.entity(placementEntityId(id))?.rootNode;
      const was = editor.current().placements.find((p) => p.id === id);
      if (node && was) void track(editor.move(id, transformAt(node.position, was.transform)));
      return;
    }
    const at = pointed();
    if (!at?.placement) return;
    if (what === 'grab') {
      holding = at.placement;
      heldLift = liftOf(at.placement);
    } else void track(editor.remove(at.placement));
  };
  /** The place input: places the copy while placing; otherwise starts placing the chosen item, except a left click, which clicks. */
  const placeInput = (input: string): void => {
    if (placing) return placeAtGhost();
    if (input === 'mouse-left') return clickPointed();
    beginPlacing(chosen);
  };
  const clickPointed = (): void => {
    const at = pointed();
    if (at?.placement) trigger('click', at.placement);
  };

  const onDown = (e: MouseEvent): void => {
    const b = BUTTONS[e.button];
    if (!b) return;
    if (placing) {
      if (b === 'mouse-right') cancelPlacing();
      else if (b === keys().place) placeAtGhost();
      return;
    }
    if (offered()) {
      const k = keys();
      if (b === k.grab) return edit('grab');
      // While holding, the only input is letting go.
      if (holding) return;
      if (b === k.delete) return edit('delete');
      if (b === k.place) return placeInput(b);
    }
    // Anyone may click a copy; a builder's left click does it too when not placing.
    if (b === 'mouse-left') clickPointed();
  };
  const onMenu = (e: Event): void => {
    if (offered() || placing) e.preventDefault();
  };
  const onKey = (e: KeyboardEvent): void => {
    const key = e.key.toLowerCase();
    // Typing in a field (the menu's search, chat) is never a building key.
    const target = e.target as HTMLElement | null;
    if (target && (target.isContentEditable || /^(input|textarea|select)$/i.test(target.tagName))) return;
    if (panelOpen() && key === 'escape') return closePanel();
    if (key === 'b' && offered()) return panelOpen() ? closePanel() : openPanel();
    if (placing && key === 'escape') return cancelPlacing();
    if (placing && (key === 'q' || key === 'e')) {
      yaw += key === 'q' ? tools().rotateStep : -tools().rotateStep;
      return showGhost();
    }
    if (!offered()) return;
    if (/^[1-9]$/.test(key)) return chooseSlot(Number(key) - 1);
    const k = keys();
    if (key === k.place) placeInput(key);
    else if (key === k.grab) edit('grab');
    else if (key === k.delete && !holding) edit('delete');
  };

  // While held, the placement follows where the visitor points; while placing, its copy does; otherwise the pointer may touch a copy.
  const follow = o.scene.onBeforeRenderObservable.add(() => {
    if (holding) {
      const node = o.entity(placementEntityId(holding))?.rootNode;
      const at = pointed();
      if (node && at) node.position.set(at.point.x, at.point.y + heldLift, at.point.z);
      return;
    }
    if (placing) {
      const at = pointed();
      if (at) {
        placing.at = snapped(at.point);
        showGhost();
      }
      return;
    }
    if (!wantsTouch()) return;
    const on = pointed()?.placement ?? null;
    if (on === touched) return;
    touched = on;
    if (on) trigger('touch', on);
  });

  let wait = 1000;
  const joinRoom = (): void => {
    const changes = loaded?.description.changes;
    if (!changes || closedRoom || !loaded) return;
    const client = createClient({ credential: 'public', tag: 'placement changes' });
    let s: ChangesSocket;
    try {
      s = (o.openSocket ?? ((u: string) => new WebSocket(u) as unknown as ChangesSocket))(changes.address);
    } catch {
      return;
    }
    socket = s;
    // One room may carry many worlds' notices: act on those naming this world, by its topic when the
    // description gives one (so the room never says which world), else by the description itself.
    const topic = changes.topic;
    const mine = loaded.descriptionUrl;
    const ours = (intent: { description?: unknown; topic?: unknown } | null): boolean =>
      topic !== undefined ? intent?.topic === topic : intent?.description === mine;
    s.addEventListener('open', () => s.send(client.hello()));
    s.addEventListener('message', (e) => {
      for (const ev of client.receive(String(e.data))) {
        if (ev.kind === 'welcomed') {
          wait = 1000;
          // A write between the last read and this join was told before we were here to hear it.
          if (editor) void track(editor.refresh());
        } else if (ev.kind === 'applied' && ev.path === 'placements') {
          const intent = ev.intent as { description?: unknown; topic?: unknown; world_seq?: unknown } | null;
          if (ours(intent) && typeof intent?.world_seq === 'number') editor?.onNotice(intent.world_seq);
        } else if (ev.kind === 'applied' && ev.path === 'palette') {
          // The palette changed (an item added, replaced or taken away). A palette write does not move
          // world_seq, so every notice is read, never compared with the last.
          const intent = ev.intent as { description?: unknown; topic?: unknown } | null;
          if (ours(intent)) void track(rereadPalette());
        }
      }
    });
    s.addEventListener('close', () => {
      if (socket !== s || closedRoom) return;
      socket = undefined;
      setTimeout(joinRoom, wait);
      wait = Math.min(wait * 2, 30_000);
    });
  };

  const ready = track(
    (async () => {
      try {
        loaded = await placementsFor({ hint, documentUrl: o.documentUrl, fetchImpl: o.fetchImpl });
      } catch (err) {
        o.warn('veml:placements:unavailable', String(err));
        return;
      }
      if (!loaded || disposed) return;
      for (const w of loaded.warnings) o.warn(w.name, w.path);
      if (!loaded.description.entities) return;
      prefabs = loaded.palette;
      offerStyles();
      fillSlots();
      chosen = slots[0] ?? null;
      const { entities, warnings } = placementEntities(loaded.snapshot, prefabs, loaded.paletteBase, style());
      for (const w of warnings) o.warn(w.name, w.path);
      const first = o.build(entities);
      for (const p of loaded.snapshot.placements) if (prefabOf(p.prefab_ref)) builds.set(p.id, first);
      await first;
      if (disposed) return;
      for (const p of loaded.snapshot.placements) {
        const prefab = prefabOf(p.prefab_ref);
        if (prefab) settle(p.id, prefab);
      }

      const edit = loaded.description.edit;
      let vouched = false;
      if (edit?.clientId) {
        const make = o.passFlow ?? ((f) => createPassFlow({ ...f, fetchImpl: (u, init) => o.fetchImpl(u, init), say, keep: o.keep, pending: o.pending, shellSignIn: o.shellSignIn, shellBase: o.shellBase, redirectUri: o.redirectUri, openWindow: o.openWindow, exitPointerLock: () => doc?.exitPointerLock?.() }));
        flow = make({
          passIssuer: edit.issuer,
          audience: edit.clientId,
          resource: loaded.description.writeOrigin,
          vouched: () => vouched,
          changed: () => {
            showNotice();
            tellSignIn();
          },
        });
      }
      tellSignIn();
      const described = loaded;
      editor = createPlacementEditor({
        description: described.description,
        descriptionUrl: described.descriptionUrl,
        snapshot: described.snapshot,
        hint,
        pass: () => flow?.token() ?? null,
        fetchImpl: o.fetchImpl,
        draw,
        redraw,
        undraw,
        notify: say,
        act: o.act,
        changed: () => showNotice(),
      });
      void track(editor.ready().then(() => {
        vouched = editor?.reason() !== 'not-vouched';
        // A sign-in made in place may have come back: its pass is sought now the store vouches.
        flow?.resume();
        // The flow knows the tab's sign-in once it has found its issuer, which may be after this world loaded.
        if (flow) void track(flow.idle().then(tellSignIn));
        // Opened to build, and not yet able to: sign in from here, with no click.
        if (editor?.reason() === 'sign-in' && hint('placements.edit') !== 'none') {
          const here = (o.signInOnArrival ?? signInRequested)();
          if (here) flow?.beginHere(here);
        }
        showNotice();
      }));

      // Clicking and pointing at copies is for every visitor; editing only where the world offers it.
      o.canvas?.addEventListener('mousedown', onDown);
      if (doc && edit) {
        noticeEl = doc.createElement('button');
        noticeEl.type = 'button';
        noticeEl.dataset.placementsSignIn = '';
        noticeEl.textContent = 'Sign in to edit this world';
        noticeEl.style.cssText = 'position:fixed;left:50%;bottom:16px;transform:translateX(-50%);display:none;padding:12px 20px;border:0;border-radius:6px;background:rgba(0,0,0,.7);color:#fff;font:15px system-ui,sans-serif;cursor:pointer;z-index:21';
        noticeEl.addEventListener('click', () => flow?.begin());
        doc.body.appendChild(noticeEl);
        // The dock: the bar's slots, and beside them the button that opens the Build menu, with a name above.
        dockStyleEl = doc.createElement('style');
        dockStyleEl.textContent = DOCK_CSS;
        doc.head.appendChild(dockStyleEl);
        dockEl = doc.createElement('div');
        dockEl.dataset.placementsDock = '';
        dockEl.style.display = 'none';
        barEl = doc.createElement('div');
        barEl.dataset.placementsBar = '';
        barEl.style.display = 'none';
        openBuildEl = doc.createElement('button');
        openBuildEl.type = 'button';
        openBuildEl.dataset.placementsOpenBuild = '';
        openBuildEl.title = 'Build (B)';
        openBuildEl.setAttribute('aria-label', 'Open the Build menu');
        openBuildEl.textContent = '⊞';
        openBuildEl.style.display = 'none';
        openBuildEl.addEventListener('click', () => (panelOpen() ? closePanel() : openPanel()));
        openBuildEl.addEventListener('pointerenter', () => showName('Build (B)'));
        openBuildEl.addEventListener('pointerleave', () => showName(null));
        nameEl = doc.createElement('div');
        nameEl.dataset.placementsDockName = '';
        nameEl.hidden = true;
        dockEl.append(nameEl, barEl, openBuildEl);
        doc.body.appendChild(dockEl);
        drawBar();
        o.canvas?.addEventListener('contextmenu', onMenu);
        doc.addEventListener('keydown', onKey);
        // Turning a phone, or resizing the window, changes how many slots fit.
        doc.defaultView?.addEventListener('resize', drawBar);
        // The menu's Build section: the whole catalog, and Add a template for a visitor with the palette scope.
        const s = createBuildSection(doc, {
          prefabs: () => prefabs,
          base: () => described.paletteBase,
          mayShow,
          choose: chooseFromCatalog,
          // The language's shapes, in a colour the visitor picks; and the tools a script put in the bar.
          shapes: () => shapes(),
          color: () => shapeColor,
          setColor: (c) => {
            shapeColor = c;
            drawBar();
            section?.refresh();
          },
          dockTools: () => [...dockTools.values()],
          canAdd: () => !!editor?.scopes().includes('palette'),
          add: addTemplate,
          readClips: async (file) => glbAnimationNames(await file.arrayBuffer()),
          tools,
          saveTools,
          // The world's own picture, for its owner, where the world says it is written.
          ...(described.description.picture
            ? {
                picture: {
                  offered: () => !!editor?.scopes().includes('owner'),
                  take: () => shootView(o.scene),
                  save: async (picture: Blob) => {
                    const r = await savePicture({ fetchImpl: o.fetchImpl, url: described.description.picture!, pass: flow?.token() ?? null, picture });
                    return r.ok ? null : r.error;
                  },
                },
              }
            : {}),
        });
        section = s;
        // The Build menu's own panel: a title, a close button, and the catalog under them.
        panelEl = doc.createElement('div');
        panelEl.dataset.buildPanel = '';
        panelEl.hidden = true;
        panelEl.setAttribute('role', 'dialog');
        panelEl.setAttribute('aria-label', 'Build');
        panelEl.style.cssText =
          'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(880px,94vw);max-height:84vh;overflow:auto;box-sizing:border-box;padding:20px 24px;background:#1b1b1b;color:#fff;font:14px system-ui,sans-serif;border:1px solid #333;border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,.5);z-index:30';
        const head = doc.createElement('div');
        head.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:14px';
        const title = doc.createElement('h2');
        title.textContent = 'Build';
        title.style.cssText = 'margin:0;font-size:22px;font-weight:700';
        const close = doc.createElement('button');
        close.type = 'button';
        close.setAttribute('aria-label', 'Close');
        close.textContent = '×';
        close.style.cssText = 'border:0;background:none;color:#fff;font:28px system-ui,sans-serif;cursor:pointer;line-height:1';
        close.addEventListener('click', closePanel);
        head.append(title, close);
        panelEl.append(head, s.body);
        // The panel's own keys and clicks stay in it: typing in its search never moves the visitor.
        panelEl.addEventListener('mousedown', (e) => e.stopPropagation());
        doc.body.appendChild(panelEl);
      }
      joinRoom();
    })(),
  );

  return {
    ready: () => ready,
    state: () => ({
      drawn: editor?.current().placements.length ?? loaded?.snapshot.placements.length ?? 0,
      worldSeq: editor?.current().world_seq ?? loaded?.snapshot.world_seq ?? 0,
      offered: offered(),
      reason: editor?.reason() ?? null,
      holding,
      chosen,
      placing: placing?.ref ?? null,
      keys: keys(),
    }),
    async idle() {
      while (pending.size > 0) await Promise.all([...pending]);
      showNotice();
    },
    addTool(name, picture, press) {
      // Only where the bar is offered, and only while it has a free slot: the visitor's items are theirs,
      // so a tool never takes one, and a full bar refuses the tool.
      if (!offered() || !barEl || slots.length >= BAR_SLOTS) return null;
      const id = `tool:${++toolCount}`;
      dockTools.set(id, { id, name, picture, press });
      fillSlots();
      drawBar();
      section?.refresh();
      return id;
    },
    removeTool(id) {
      if (!dockTools.delete(id)) return false;
      fillSlots();
      drawBar();
      section?.refresh();
      return true;
    },
    clearTools() {
      dockTools.clear();
      fillSlots();
      drawBar();
      section?.refresh();
    },
    dispose() {
      disposed = true;
      closedRoom = true;
      // The world is left: none of its styles are offered any more.
      o.offerStyles?.({ names: [], current: () => undefined, choose: () => {} });
      socket?.close();
      cancelPlacing();
      dockTools.clear();
      o.scene.onBeforeRenderObservable.remove(follow);
      o.canvas?.removeEventListener('mousedown', onDown);
      o.canvas?.removeEventListener('contextmenu', onMenu);
      doc?.removeEventListener('keydown', onKey);
      doc?.defaultView?.removeEventListener('resize', drawBar);
      panelEl?.remove();
      noticeEl?.remove();
      dockEl?.remove();
      dockStyleEl?.remove();
      clearTimeout(nameTimer);
      toast?.remove();
      flow?.dispose();
      editor?.dispose();
    },
  };
}
