/**
 * A palette item's triggers, run on one placed copy. The bindings are data
 * from the item's sidecar: nothing from the palette is ever run as code. A
 * binding names when it runs (`on`), what it does with one of the copy's own
 * glTF clips (`animate`), and a world action to fire (`action`), which the
 * world's own script receives with the placement's id. Values the shell does
 * not know are ignored.
 *
 * No engine import: the clips are the scene's animation groups, which the
 * view hands in, so this module adds nothing to first paint.
 */
import type { PrefabBinding } from './placements';

/** One clip of a placed copy: an animation group, as far as triggers use it. */
export interface Clip {
  readonly name: string;
  readonly isPlaying: boolean;
  play(loop?: boolean): unknown;
  stop(): unknown;
}

const TRIGGERS = new Set(['click', 'touch', 'place']);
const ANIMATES = new Set(['play', 'stop', 'toggle']);

/**
 * The clips that belong to one copy: the groups animating a node at or
 * under its root. Each copy loads its own model, so each has its own groups,
 * with the same names as every other copy's.
 */
export function clipsUnder<G extends Clip & { targetedAnimations: readonly { target: unknown }[] }>(groups: readonly G[], root: unknown): G[] {
  if (!root) return [];
  const under = (t: unknown): boolean => {
    if (t === root) return true;
    const node = t as { isDescendantOf?: (ancestor: unknown) => boolean } | null;
    return typeof node?.isDescendantOf === 'function' && node.isDescendantOf(root);
  };
  return groups.filter((g) => g.targetedAnimations.some((a) => under(a.target)));
}

/** Whether any binding drives a clip, so that the copy's clips start still rather than as the model loaded them. */
export const hasAnimate = (bindings: readonly PrefabBinding[] | undefined): boolean =>
  !!bindings?.some((b) => TRIGGERS.has(b.on) && typeof b.animate === 'string' && ANIMATES.has(b.animate));

/** Runs every binding for `on` on one copy: its clip first, then its action, once each. */
export function fireTrigger(o: {
  on: string;
  bindings: readonly PrefabBinding[];
  clips: readonly Clip[];
  placement: string;
  prefab_ref: string;
  act: (name: string, data: unknown) => void;
}): void {
  if (!TRIGGERS.has(o.on)) return;
  for (const b of o.bindings) {
    if (b.on !== o.on) continue;
    if (typeof b.animate === 'string' && ANIMATES.has(b.animate)) {
      // No clip named: every clip the copy has.
      const targets = b.clip === undefined ? o.clips : o.clips.filter((c) => c.name === b.clip);
      for (const c of targets) {
        if (b.animate === 'stop' || (b.animate === 'toggle' && c.isPlaying)) c.stop();
        else c.play(b.loop === true);
      }
    }
    if (typeof b.action === 'string' && b.action !== '') o.act(b.action, { id: o.placement, prefab_ref: o.prefab_ref, on: o.on });
  }
}
