/**
 * The Build section of the in-world menu: every item in the world's
 * palette, with its picture or its name, and a search over the names.
 * Choosing an item hands it to the edit bar, which starts placing it. A
 * visitor whose scopes include `palette` is also offered Add a template: a
 * model, a name, an optional picture and an optional trigger, whose clip is
 * picked from the model's own animations. Under the catalog sit the visitor's
 * Placement tools: grid snap, grid size and how far Q and E turn.
 *
 * DOM only; the view gives it the palette, what choosing does, and how to
 * add, so it holds no store and no scene.
 */
import type { Prefab } from './placements';
import type { TemplateBinding } from './paletteWrite';
import type { DockTool } from './placementsView';

/** What the Add form hands over. */
export interface TemplateDraft {
  name: string;
  model: Blob;
  picture?: Blob;
  bindings: TemplateBinding[];
}

export interface BuildSectionOptions {
  prefabs: () => readonly Prefab[];
  /** What a picture's address resolves against: the palette's own. */
  base: () => string;
  /** Whether a picture at this address may be shown: the page asks for it as an image, with that site's cookies. Absent: any. */
  mayShow?: (address: string) => boolean;
  choose: (ref: string) => void;
  /** The language's shapes offered as items (empty where the world offers none), the colour the next one is placed in, and setting it. */
  shapes?: () => readonly Prefab[];
  color?: () => string;
  setColor?: (color: string) => void;
  /** The tools a world's script put in the bar; each entry presses one. */
  dockTools?: () => readonly DockTool[];
  /** Whether Add a template is offered: the visitor's scopes include `palette`. */
  canAdd: () => boolean;
  /** Adds a template; resolves with what went wrong in plain words, or null. */
  add: (draft: TemplateDraft) => Promise<string | null>;
  /** The animation names in a chosen model file. */
  readClips: (file: Blob) => Promise<string[]>;
  /** The visitor's building tools, and where a change to them is kept (their settings). Absent: no Placement rows. */
  tools?: () => BuildingTools;
  saveTools?: (tools: BuildingTools) => void;
  /** The world's own picture, for its owner. Absent or not offered: no Picture rows. */
  picture?: {
    offered: () => boolean;
    /** The current view, or null where it cannot be taken. */
    take: () => Promise<Blob | null>;
    /** Keeps it as the world's picture; resolves with what went wrong in plain words, or null. */
    save: (picture: Blob) => Promise<string | null>;
  };
}

/** The visitor's building tools (their settings): grid snap, its size in metres, the Q/E turn in degrees. */
export interface BuildingTools {
  snap: boolean;
  grid: number;
  rotateStep: number;
}

export interface BuildSection {
  body: HTMLElement;
  /** Draws the catalog and the Add form again from what the options say now. */
  refresh(): void;
}

const CSS = `
[data-build] input[type=search]{width:100%;box-sizing:border-box;margin-bottom:10px;padding:10px 14px;font:14px system-ui,sans-serif;color:#fff;
  background:#2a2a2a;border:1px solid #3a3a3a;border-radius:8px}
[data-build-grid]{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:12px;max-height:46vh;overflow:auto;padding:2px}
[data-build-item]{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;height:128px;padding:10px 6px;
  overflow:hidden;cursor:pointer;color:#fff;font:600 13px system-ui,sans-serif;background:#262626;border:1px solid #3a3a3a;border-radius:8px}
[data-build-item]:hover{border-color:#7aa2ff}
[data-build-item][hidden]{display:none}
[data-build-item] img{width:64px;height:64px;object-fit:contain;border-radius:6px;background:#333}
[data-build-item] span{text-align:center;line-height:1.2}
[data-build-add]{margin-top:14px;padding-top:10px;border-top:1px solid rgba(255,255,255,.2)}
[data-build-upload]{margin-top:10px;width:100%;padding:8px;font:inherit;color:#fff;cursor:pointer;
  background:rgba(122,162,255,.35);border:1px solid rgba(255,255,255,.35);border-radius:6px}
`;

const ON: ReadonlyArray<[string, string]> = [
  ['', 'No trigger'],
  ['click', 'When clicked'],
  ['touch', 'When pointed at'],
  ['place', 'When placed'],
];
const ANIMATE: ReadonlyArray<[string, string]> = [
  ['toggle', 'Play, then stop'],
  ['play', 'Play'],
  ['stop', 'Stop'],
];

const nameOf = (p: Prefab): string => p.label ?? p.ref.split('/').pop()?.replace(/\.glb$/i, '') ?? p.ref;

export function createBuildSection(doc: Document, o: BuildSectionOptions): BuildSection {
  const body = doc.createElement('div');
  body.setAttribute('data-build', '');
  const style = doc.createElement('style');
  style.textContent = CSS;

  const search = doc.createElement('input');
  search.type = 'search';
  search.placeholder = 'Search';
  search.setAttribute('aria-label', 'Search the palette');
  search.setAttribute('data-build-search', '');
  const grid = doc.createElement('div');
  grid.setAttribute('data-build-grid', '');

  // The colour the next shape is placed in; shown only where the world offers shapes.
  const shapesBox = doc.createElement('div');
  shapesBox.setAttribute('data-build-shapes', '');
  shapesBox.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:13px';
  const colorLabel = doc.createElement('label');
  colorLabel.textContent = 'Shape colour';
  const color = doc.createElement('input');
  color.type = 'color';
  color.setAttribute('data-build-color', '');
  colorLabel.htmlFor = color.id = 'webverse-build-color';
  color.addEventListener('change', () => o.setColor?.(color.value));
  shapesBox.append(colorLabel, color);

  const select = (field: string, label: string, options: ReadonlyArray<[string, string]>): [HTMLLabelElement, HTMLSelectElement] => {
    const l = doc.createElement('label');
    l.textContent = label;
    const s = doc.createElement('select');
    s.setAttribute('data-build-field', field);
    l.htmlFor = s.id = `webverse-build-${field}`;
    for (const [value, text] of options) {
      const opt = doc.createElement('option');
      opt.value = value;
      opt.textContent = text;
      s.appendChild(opt);
    }
    return [l, s];
  };
  const input = (field: string, label: string, type: string): [HTMLLabelElement, HTMLInputElement] => {
    const l = doc.createElement('label');
    l.textContent = label;
    const i = doc.createElement('input');
    i.type = type;
    i.setAttribute('data-build-field', field);
    l.htmlFor = i.id = `webverse-build-${field}`;
    return [l, i];
  };

  const add = doc.createElement('div');
  add.setAttribute('data-build-add', '');
  const heading = doc.createElement('h3');
  heading.textContent = 'Add a template';
  heading.style.cssText = 'margin:0 0 6px;font-size:15px;font-weight:600';
  const [glbLabel, glb] = input('glb', 'Model (.glb)', 'file');
  glb.accept = '.glb,model/gltf-binary';
  const [nameLabel, name] = input('name', 'Name', 'text');
  name.maxLength = 64;
  name.autocomplete = 'off';
  const [pictureLabel, picture] = input('picture', 'Picture (optional)', 'file');
  picture.accept = 'image/png,image/jpeg,image/webp';
  const [onLabel, on] = select('on', 'Trigger', ON);
  const [animateLabel, animate] = select('animate', 'Animation', ANIMATE);
  const [clipLabel, clip] = select('clip', 'Clip', [['', 'All of the model’s clips']]);
  const [loopLabel, loop] = input('loop', '', 'checkbox');
  loopLabel.append(loop, doc.createTextNode(' Loop'));
  const [actionLabel, action] = input('action', 'World action (optional)', 'text');
  action.autocomplete = 'off';
  const upload = doc.createElement('button');
  upload.type = 'button';
  upload.textContent = 'Add';
  upload.setAttribute('data-build-upload', '');
  const note = doc.createElement('p');
  note.setAttribute('data-build-note', '');
  note.setAttribute('role', 'status');
  note.style.cssText = 'min-height:1.2em;margin:6px 0 0;font-size:12px;opacity:.85';
  const triggerRows = [animateLabel, animate, clipLabel, clip, loopLabel, actionLabel, action];
  add.append(heading, glbLabel, glb, nameLabel, name, pictureLabel, picture, onLabel, on, ...triggerRows, upload, note);

  // Placement: the visitor's grid snap, its size, and how far Q and E turn, kept in their settings.
  const placement = doc.createElement('div');
  placement.setAttribute('data-build-placement', '');
  const placementHeading = doc.createElement('h3');
  placementHeading.textContent = 'Placement';
  placementHeading.style.cssText = heading.style.cssText;
  placementHeading.style.marginTop = '14px';
  const [snapLabel, snap] = input('snap', '', 'checkbox');
  snapLabel.append(snap, doc.createTextNode(' Snap to a grid'));
  const [gridLabel, gridSize] = select('grid', 'Grid size', [['0.25', '25 cm'], ['0.5', '50 cm'], ['1', '1 m'], ['2', '2 m']]);
  const [stepLabel, step] = select('rotate-step', 'Q and E turn by', ['5', '15', '30', '45', '90'].map((d): [string, string] => [d, `${d}°`]));
  placement.append(placementHeading, snapLabel, gridLabel, gridSize, stepLabel, step);
  placement.hidden = !o.saveTools;
  const saveTools = (): void => o.saveTools?.({ snap: snap.checked, grid: Number(gridSize.value), rotateStep: Number(step.value) });
  for (const el of [snap, gridSize, step]) el.addEventListener('change', saveTools);
  // The world's own picture, for its owner: take the view, see it, keep it or take another.
  const shotBox = doc.createElement('div');
  shotBox.setAttribute('data-build-picture', '');
  const shotHeading = doc.createElement('h3');
  shotHeading.textContent = 'World picture';
  shotHeading.style.cssText = heading.style.cssText;
  shotHeading.style.marginTop = '14px';
  const shotHelp = doc.createElement('p');
  shotHelp.textContent = 'Stand where the world looks its best, then take its picture. It is what people see on its card.';
  shotHelp.style.cssText = 'margin:0 0 6px;font-size:12px;opacity:.85';
  const button = (attr: string, text: string): HTMLButtonElement => {
    const b = doc.createElement('button');
    b.type = 'button';
    b.setAttribute(attr, '');
    b.textContent = text;
    return b;
  };
  const take = button('data-build-picture-take', 'Take a picture');
  const shot = doc.createElement('div');
  shot.setAttribute('data-build-picture-shot', '');
  shot.hidden = true;
  const shotImg = doc.createElement('img');
  shotImg.alt = 'The picture just taken';
  shotImg.style.cssText = 'display:block;width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:6px;margin:6px 0';
  const keep = button('data-build-picture-keep', 'Keep');
  const retake = button('data-build-picture-retake', 'Take another');
  shot.append(shotImg, keep, retake);
  const said = doc.createElement('p');
  said.setAttribute('data-build-picture-said', '');
  said.setAttribute('role', 'status');
  said.style.cssText = note.style.cssText;
  shotBox.append(shotHeading, shotHelp, take, shot, said);
  let taken: Blob | null = null;
  const takeShot = async (): Promise<void> => {
    if (!o.picture) return;
    said.textContent = '';
    taken = await o.picture.take();
    if (!taken) {
      said.textContent = 'The view could not be taken here.';
      return;
    }
    const url = (doc.defaultView?.URL ?? URL).createObjectURL?.(taken);
    if (url) shotImg.src = url;
    shot.hidden = false;
    take.hidden = true;
  };
  take.addEventListener('click', () => void takeShot());
  retake.addEventListener('click', () => void takeShot());
  keep.addEventListener('click', () => {
    if (!o.picture || !taken) return;
    said.textContent = 'Keeping…';
    void o.picture.save(taken).then((error) => {
      said.textContent = error ?? 'Kept. It is the world’s picture now.';
      if (!error) {
        shot.hidden = true;
        take.hidden = false;
      }
    });
  });

  body.append(style, search, shapesBox, grid, placement, shotBox, add);

  const showTrigger = (): void => {
    for (const el of triggerRows) el.hidden = on.value === '';
  };
  on.addEventListener('change', showTrigger);
  showTrigger();

  /** A tile: the picture, if there is one, over the name. */
  const tile = (label: string, picture: string | null, press: () => void): HTMLButtonElement => {
    const cell = doc.createElement('button');
    cell.type = 'button';
    cell.setAttribute('data-build-item', '');
    cell.title = label;
    if (picture && o.mayShow?.(picture) !== false) {
      const img = doc.createElement('img');
      img.src = picture;
      img.alt = label;
      cell.appendChild(img);
    }
    const name = doc.createElement('span');
    name.textContent = label;
    cell.appendChild(name);
    cell.addEventListener('click', press);
    return cell;
  };

  // One catalog, as the visitor thinks of it: the world's items, the
  // language's shapes and a script's tools side by side, one search over all.
  const drawGrid = (): void => {
    const q = search.value.trim().toLowerCase();
    const base = o.base();
    const matches = (...names: string[]): boolean => q === '' || names.some((n) => n.toLowerCase().includes(q));
    const shapes = o.shapes?.() ?? [];
    shapesBox.hidden = shapes.length === 0;
    color.value = o.color?.() ?? '#9a9a9a';
    const pictureOf = (p: Prefab): string | null => {
      if (!p.thumbnail) return null;
      try {
        return new URL(p.thumbnail, base).href;
      } catch {
        return p.thumbnail;
      }
    };
    grid.replaceChildren(
      ...o.prefabs().map((p) => {
        const label = nameOf(p);
        const cell = tile(label, pictureOf(p), () => o.choose(p.ref));
        cell.dataset.prefab = p.ref;
        cell.hidden = !matches(label, p.ref);
        return cell;
      }),
      ...shapes.map((p) => {
        const label = nameOf(p);
        const cell = tile(label, null, () => o.choose(p.ref));
        cell.setAttribute('data-build-shape', p.shape ?? '');
        cell.dataset.prefab = p.ref;
        cell.style.background = `linear-gradient(rgba(0,0,0,.35),rgba(0,0,0,.35)),${color.value}`;
        cell.hidden = !matches(label);
        return cell;
      }),
      ...(o.dockTools?.() ?? []).map((t) => {
        const cell = tile(t.name, t.picture, () => t.press());
        cell.setAttribute('data-build-tool', t.id);
        cell.hidden = !matches(t.name);
        return cell;
      }),
    );
  };
  search.addEventListener('input', drawGrid);

  // A chosen model names the template after its file, and offers its own clips.
  let clipsFor: Blob | undefined;
  glb.addEventListener('change', () => {
    const file = glb.files?.[0];
    if (!file) return;
    if (name.value.trim() === '' && 'name' in file) name.value = String((file as File).name).replace(/\.glb$/i, '').replace(/[^A-Za-z0-9_-]/g, '-').slice(0, 64);
    clipsFor = file;
    void o.readClips(file).then((names) => {
      if (clipsFor !== file) return;
      clip.replaceChildren(clip.options[0]!);
      for (const n of names) {
        const opt = doc.createElement('option');
        opt.value = opt.textContent = n;
        clip.appendChild(opt);
      }
    });
  });

  let busy = false;
  upload.addEventListener('click', () => {
    if (busy) return;
    const model = glb.files?.[0];
    if (!model) {
      note.textContent = 'Choose a model (.glb) first.';
      return;
    }
    const pic = picture.files?.[0];
    const bindings: TemplateBinding[] =
      on.value === ''
        ? []
        : [
            {
              on: on.value,
              animate: animate.value,
              ...(clip.value !== '' ? { clip: clip.value } : {}),
              loop: loop.checked,
              ...(action.value.trim() !== '' ? { action: action.value.trim() } : {}),
            },
          ];
    busy = true;
    note.textContent = 'Adding…';
    void o
      .add({ name: name.value.trim(), model, ...(pic ? { picture: pic } : {}), bindings })
      .then((error) => {
        note.textContent = error ?? `Added ${name.value.trim()}. It is in everyone’s palette now.`;
      })
      .finally(() => {
        busy = false;
      });
  });

  const refresh = (): void => {
    drawGrid();
    add.hidden = !o.canAdd();
    shotBox.hidden = !o.picture?.offered();
    const t = o.tools?.();
    if (t) {
      snap.checked = t.snap;
      gridSize.value = String(t.grid);
      step.value = String(t.rotateStep);
    }
  };
  refresh();
  return { body, refresh };
}
